INSERT OR IGNORE INTO verses (id, ref, book, chapter, verse, text, text_normalized, text_html, testament, translation_key, dialect, tags, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(6001, 'Joshua 23:8', 'Joshua', 23, 8, '&nbsp;د دې په ځائ، د مالِک خُدائ هم هغه شان وفادار اوسئ، لکه څنګه چې تر اوسه پورې وفادار يئ.', NULL, '&nbsp;د دې په ځائ، د مالِک خُدائ هم هغه شان وفادار اوسئ، لکه څنګه چې تر اوسه پورې وفادار يئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6002, 'Joshua 23:9', 'Joshua', 23, 9, '&nbsp;چې تاسو مخ په وړاندې تلئ نو مالِک خُدائ لوئ لوئ او تکړه قومونه شړلى دى او تر اوسه پورې څوک د دې قابل نۀ دى چې ستاسو خِلاف ودريږى.', NULL, '&nbsp;چې تاسو مخ په وړاندې تلئ نو مالِک خُدائ لوئ لوئ او تکړه قومونه شړلى دى او تر اوسه پورې څوک د دې قابل نۀ دى چې ستاسو خِلاف ودريږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6003, 'Joshua 23:10', 'Joshua', 23, 10, '&nbsp;ستاسو هر يو کس زر سړو له منډه ورکولے شى، ځکه چې مالِک خُدائ ستاسو خُدائ پاک ستاسو دپاره جنګ کوى، هم هغه شان لکه څنګه چې هغۀ وعده کړې ده.', NULL, '&nbsp;ستاسو هر يو کس زر سړو له منډه ورکولے شى، ځکه چې مالِک خُدائ ستاسو خُدائ پاک ستاسو دپاره جنګ کوى، هم هغه شان لکه څنګه چې هغۀ وعده کړې ده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6004, 'Joshua 23:11', 'Joshua', 23, 11, '&nbsp;نو بيا کوشش کوئ چې د مالِک خُدائ خپل خُدائ پاک سره مينه وکړئ.', NULL, '&nbsp;نو بيا کوشش کوئ چې د مالِک خُدائ خپل خُدائ پاک سره مينه وکړئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6005, 'Joshua 23:12', 'Joshua', 23, 12, '&nbsp;کۀ تاسو بې‌وفا شئ او د هغه قومونو سره اِتحاد وکړئ کوم قومونه چې تر اوسه پورې ستاسو سره پاتې دى او د هغوئ سره ودونه وکړئ،', NULL, '&nbsp;کۀ تاسو بې‌وفا شئ او د هغه قومونو سره اِتحاد وکړئ کوم قومونه چې تر اوسه پورې ستاسو سره پاتې دى او د هغوئ سره ودونه وکړئ،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6006, 'Joshua 23:13', 'Joshua', 23, 13, '&nbsp;نو تاسو يقين وکړئ چې کله تاسو مخ په وړاندې ځئ نو مالِک خُدائ ستاسو خُدائ پاک به نور هغه قومونه ونۀ شړى. او هغوئ به ستاسو دپاره د دام يا د کندې په شان خطرناک وى او د کوړې په شان به داسې دردناک وى لکه چې ستاسو ملا ورباندې ووهلے شى او يا چې ازغى ستاسو سترګې ړندې کړى. او دا به په هغه وخت ختم شى چې ستاسو يو کس هم په دې ښائسته مُلک کښې پاتې نۀ شى هغه مُلک چې مالِک خُدائ ستاسو خُدائ پاک تاسو له درکړے دے.', NULL, '&nbsp;نو تاسو يقين وکړئ چې کله تاسو مخ په وړاندې ځئ نو مالِک خُدائ ستاسو خُدائ پاک به نور هغه قومونه ونۀ شړى. او هغوئ به ستاسو دپاره د دام يا د کندې په شان خطرناک وى او د کوړې په شان به داسې دردناک وى لکه چې ستاسو ملا ورباندې ووهلے شى او يا چې ازغى ستاسو سترګې ړندې کړى. او دا به په هغه وخت ختم شى چې ستاسو يو کس هم په دې ښائسته مُلک کښې پاتې نۀ شى هغه مُلک چې مالِک خُدائ ستاسو خُدائ پاک تاسو له درکړے دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6007, 'Joshua 23:14', 'Joshua', 23, 14, '&nbsp;اوس زما د مرګ وخت نزدې دے او تاسو هر يو کس د زړۀ د کومې نه خبر يئ چې مالِک خُدائ ستاسو خُدائ پاک چې هره يوه وعده کړې ده نو هغه يې پوره کړې ده، داسې يوه وعده هم نشته چې پوره شوې نۀ وى.', NULL, '&nbsp;اوس زما د مرګ وخت نزدې دے او تاسو هر يو کس د زړۀ د کومې نه خبر يئ چې مالِک خُدائ ستاسو خُدائ پاک چې هره يوه وعده کړې ده نو هغه يې پوره کړې ده، داسې يوه وعده هم نشته چې پوره شوې نۀ وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6008, 'Joshua 23:15', 'Joshua', 23, 15, '&nbsp;خو لکه څنګه چې هغۀ کومه وعده کړې ده او هره يوه يې پوره کړې ده، نو داسې کۀ تاسو د هغۀ نافرمانى وکړئ نو خُدائ پاک به هغه افتونه هم راولى. تاسو به تباه کړى او د هغه ښۀ مُلک نه به مو ورک کړى کوم ښۀ مُلک چې مالِک خُدائ ستاسو خُدائ پاک تاسو له درکړے وو.', NULL, '&nbsp;خو لکه څنګه چې هغۀ کومه وعده کړې ده او هره يوه يې پوره کړې ده، نو داسې کۀ تاسو د هغۀ نافرمانى وکړئ نو خُدائ پاک به هغه افتونه هم راولى. تاسو به تباه کړى او د هغه ښۀ مُلک نه به مو ورک کړى کوم ښۀ مُلک چې مالِک خُدائ ستاسو خُدائ پاک تاسو له درکړے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6009, 'Joshua 23:16', 'Joshua', 23, 16, '&nbsp;کۀ تاسو هغه لوظ مات کړئ چې مالِک خُدائ ستاسو خُدائ پاک د هغې سر ته رسولو حُکم درکړے دے او تاسو د نورو معبودانو خِدمت او عبادت وکړئ، نو بيا به هغه په خپله غصه کښې تاسو له سزا درکړى، نو ډېر زر به ستاسو يو کس هم په دې ښۀ مُلک کښې پاتې نۀ شى چې کوم هغۀ درکړے دے.“', NULL, '&nbsp;کۀ تاسو هغه لوظ مات کړئ چې مالِک خُدائ ستاسو خُدائ پاک د هغې سر ته رسولو حُکم درکړے دے او تاسو د نورو معبودانو خِدمت او عبادت وکړئ، نو بيا به هغه په خپله غصه کښې تاسو له سزا درکړى، نو ډېر زر به ستاسو يو کس هم په دې ښۀ مُلک کښې پاتې نۀ شى چې کوم هغۀ درکړے دے.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6010, 'Joshua 24:1', 'Joshua', 24, 1, '&nbsp;يشوَع په شِکم کښې د بنى اِسرائيلو ټولې قبيلې راغونډې کړې. هغۀ مالِکان، مشران، قاضيان او د بنى اِسرائيلو آفسران راوغوښتل او هغوئ د خُدائ پاک حضور ته راغلل.', NULL, '&nbsp;يشوَع په شِکم کښې د بنى اِسرائيلو ټولې قبيلې راغونډې کړې. هغۀ مالِکان، مشران، قاضيان او د بنى اِسرائيلو آفسران راوغوښتل او هغوئ د خُدائ پاک حضور ته راغلل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6011, 'Joshua 24:2', 'Joshua', 24, 2, '&nbsp;يشوَع خلقو ته وفرمائيل، ”مالِک خُدائ د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، ډېر وخت مخکښې، ستاسو پلار نيکۀ، سره د اِبراهيم او نحور د پلار تارح، د فرات سيند نه اخوا اوسېدل او هغوئ د نورو معبودانو عبادت کولو.', NULL, '&nbsp;يشوَع خلقو ته وفرمائيل، ”مالِک خُدائ د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، ډېر وخت مخکښې، ستاسو پلار نيکۀ، سره د اِبراهيم او نحور د پلار تارح، د فرات سيند نه اخوا اوسېدل او هغوئ د نورو معبودانو عبادت کولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6012, 'Joshua 24:3', 'Joshua', 24, 3, '&nbsp;بيا ما ستاسو پلار نيکۀ اِبراهيم د فرات سيند نه اخوا مُلک نه روان کړو او د کنعان په ټول مُلک کښې مې وګرځولو. ما هغۀ له ډېر اولاد ورکړو. ما هغۀ له اِسحاق ورکړو،', NULL, '&nbsp;بيا ما ستاسو پلار نيکۀ اِبراهيم د فرات سيند نه اخوا مُلک نه روان کړو او د کنعان په ټول مُلک کښې مې وګرځولو. ما هغۀ له ډېر اولاد ورکړو. ما هغۀ له اِسحاق ورکړو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6013, 'Joshua 24:4', 'Joshua', 24, 4, '&nbsp;او اِسحاق له مې يعقوب او عِيسو ورکړل. ما عِيسو له د ادوم د غرونو مُلک ورکړو چې خپل ميراث يې شى، خو ستاسو پلار نيکۀ يعقوب او د هغۀ بچى لاندې مِصر ته لاړل.', NULL, '&nbsp;او اِسحاق له مې يعقوب او عِيسو ورکړل. ما عِيسو له د ادوم د غرونو مُلک ورکړو چې خپل ميراث يې شى، خو ستاسو پلار نيکۀ يعقوب او د هغۀ بچى لاندې مِصر ته لاړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6014, 'Joshua 24:5', 'Joshua', 24, 5, '&nbsp;ما بيا موسىٰ او هارون ولېږل او په مِصر باندې مې لوئ افتونه راوستل او د هغې نه پس ما تاسو راوويستلئ.', NULL, '&nbsp;ما بيا موسىٰ او هارون ولېږل او په مِصر باندې مې لوئ افتونه راوستل او د هغې نه پس ما تاسو راوويستلئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6015, 'Joshua 24:6', 'Joshua', 24, 6, '&nbsp;ما ستاسو پلار نيکۀ د مِصر نه راوويستل او مِصريان د جنګى ګاډو او په آسونو سوارو کسانو سره په هغوئ پسې وُو. خو کله چې ستاسو پلار نيکۀ بحرِقُلزم ته ورسېدل', NULL, '&nbsp;ما ستاسو پلار نيکۀ د مِصر نه راوويستل او مِصريان د جنګى ګاډو او په آسونو سوارو کسانو سره په هغوئ پسې وُو. خو کله چې ستاسو پلار نيکۀ بحرِقُلزم ته ورسېدل', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6016, 'Joshua 24:7', 'Joshua', 24, 7, '&nbsp;نو هغوئ ما ته د مدد دپاره فرياد وکړو او ما د هغوئ او د مِصريانو په مينځ کښې تيارۀ راوستله. ما مِصريان په سمندر لاهُو کړل او هغوئ مې ورډُوب کړل. تاسو په خپلو سترګو وليدل چې ما په مِصر څۀ کړى دى. تاسو تر ډېره وخته پورې په هغه بيابان کښې اوسېدئ.', NULL, '&nbsp;نو هغوئ ما ته د مدد دپاره فرياد وکړو او ما د هغوئ او د مِصريانو په مينځ کښې تيارۀ راوستله. ما مِصريان په سمندر لاهُو کړل او هغوئ مې ورډُوب کړل. تاسو په خپلو سترګو وليدل چې ما په مِصر څۀ کړى دى. تاسو تر ډېره وخته پورې په هغه بيابان کښې اوسېدئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6017, 'Joshua 24:8', 'Joshua', 24, 8, '&nbsp;بيا ما تاسو د اموريانو مُلک ته راوستلئ، کوم چې د اُردن نمرخاتۀ طرف ته اوسېدل. هغوئ ستاسو سره جنګ وکړو، خو ما تاسو له په هغوئ باندې فتح درکړه. تاسو د هغوئ مُلک قبضه کړو او چې تاسو مخ په وړاندې تلئ نو هغوئ مو تباه کول.', NULL, '&nbsp;بيا ما تاسو د اموريانو مُلک ته راوستلئ، کوم چې د اُردن نمرخاتۀ طرف ته اوسېدل. هغوئ ستاسو سره جنګ وکړو، خو ما تاسو له په هغوئ باندې فتح درکړه. تاسو د هغوئ مُلک قبضه کړو او چې تاسو مخ په وړاندې تلئ نو هغوئ مو تباه کول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6018, 'Joshua 24:9', 'Joshua', 24, 9, '&nbsp;بيا د موآب بادشاه صفور زوئ بلق ستاسو خِلاف جنګ وکړو. هغۀ د بعور زوئ بلعام راوغوښتو او ورته يې ووئيل چې په تاسو لعنت ووائى.', NULL, '&nbsp;بيا د موآب بادشاه صفور زوئ بلق ستاسو خِلاف جنګ وکړو. هغۀ د بعور زوئ بلعام راوغوښتو او ورته يې ووئيل چې په تاسو لعنت ووائى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6019, 'Joshua 24:10', 'Joshua', 24, 10, '&nbsp;خو ما بلعام ته غوږ نۀ نيولو، نو ځکه هغۀ تاسو له برکت درکړو، او داسې ما تاسو د بلق نه بچ کړئ.', NULL, '&nbsp;خو ما بلعام ته غوږ نۀ نيولو، نو ځکه هغۀ تاسو له برکت درکړو، او داسې ما تاسو د بلق نه بچ کړئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6020, 'Joshua 24:11', 'Joshua', 24, 11, '&nbsp;تاسو د اُردن نه پورې وتئ او يريحو ته راغلئ. د يريحو سړو ستاسو خِلاف جنګ وکړو، هم هغه شان چې څنګه اموريانو، فرزيانو، کنعانيانو، حِتيانو، جرجاسيانو، حِويانو او يبوسيانو کړى وُو. خو ما تاسو له په هغه ټولو باندې فتح درکړه.', NULL, '&nbsp;تاسو د اُردن نه پورې وتئ او يريحو ته راغلئ. د يريحو سړو ستاسو خِلاف جنګ وکړو، هم هغه شان چې څنګه اموريانو، فرزيانو، کنعانيانو، حِتيانو، جرجاسيانو، حِويانو او يبوسيانو کړى وُو. خو ما تاسو له په هغه ټولو باندې فتح درکړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6021, 'Joshua 24:12', 'Joshua', 24, 12, '&nbsp;چې تاسو مخ په وړاندې تلئ نو ما هغوئ د دې دپاره په وارخطايۍ آخته کړل چې هغه دوه امورى بادشاهان وشړم، دا کار ستاسو د تُورو او ليندو په ذريعه نۀ وو شوے.', NULL, '&nbsp;چې تاسو مخ په وړاندې تلئ نو ما هغوئ د دې دپاره په وارخطايۍ آخته کړل چې هغه دوه امورى بادشاهان وشړم، دا کار ستاسو د تُورو او ليندو په ذريعه نۀ وو شوے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6022, 'Joshua 24:13', 'Joshua', 24, 13, '&nbsp;ما تاسو له يو داسې زمکه درکړه چې تاسو هيڅکله کَرلې نۀ وه او داسې ښارونه مې درکړل چې تاسو جوړ کړى نۀ وُو. اوس تاسو هلته اوسېږئ او د هغه باغونو نه انګور خورئ چې تاسو کَرلى نۀ دى او د هغه ونو نه د زيتُونو مېوه خورئ چې تاسو کَرلى نۀ دى.“', NULL, '&nbsp;ما تاسو له يو داسې زمکه درکړه چې تاسو هيڅکله کَرلې نۀ وه او داسې ښارونه مې درکړل چې تاسو جوړ کړى نۀ وُو. اوس تاسو هلته اوسېږئ او د هغه باغونو نه انګور خورئ چې تاسو کَرلى نۀ دى او د هغه ونو نه د زيتُونو مېوه خورئ چې تاسو کَرلى نۀ دى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6023, 'Joshua 24:14', 'Joshua', 24, 14, '&nbsp;نو يشوَع فرمائيل چې، ”د مالِک خُدائ نه يرېږئ او په اخلاص او ايماندارۍ سره د هغۀ خِدمت وکړئ. او د هغه معبودانو نه ځان خلاص کړئ چې ستاسو پلار نيکۀ په مسوپتاميه او مِصر کښې د هغوئ عبادت کولو او صِرف د مالِک خُدائ خِدمت کوئ.', NULL, '&nbsp;نو يشوَع فرمائيل چې، ”د مالِک خُدائ نه يرېږئ او په اخلاص او ايماندارۍ سره د هغۀ خِدمت وکړئ. او د هغه معبودانو نه ځان خلاص کړئ چې ستاسو پلار نيکۀ په مسوپتاميه او مِصر کښې د هغوئ عبادت کولو او صِرف د مالِک خُدائ خِدمت کوئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6024, 'Joshua 24:15', 'Joshua', 24, 15, '&nbsp;کۀ ستاسو زړۀ نۀ کيږى چې د هغۀ خِدمت وکړئ، نو نن دا فېصله وکړئ چې د چا خِدمت به کوئ، د هغه معبودانو چې ستاسو پلار نيکۀ په مسوپتاميه کښې د هغوئ عبادت کولو يا د اموريانو د معبودانو، چې د چا په مُلک کښې تاسو اوس اوسېږئ. خو پاتې شوه زما او زما د خاندان خبره، نو مونږ به د مالِک خُدائ خِدمت کوُو.“', NULL, '&nbsp;کۀ ستاسو زړۀ نۀ کيږى چې د هغۀ خِدمت وکړئ، نو نن دا فېصله وکړئ چې د چا خِدمت به کوئ، د هغه معبودانو چې ستاسو پلار نيکۀ په مسوپتاميه کښې د هغوئ عبادت کولو يا د اموريانو د معبودانو، چې د چا په مُلک کښې تاسو اوس اوسېږئ. خو پاتې شوه زما او زما د خاندان خبره، نو مونږ به د مالِک خُدائ خِدمت کوُو.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6025, 'Joshua 24:16', 'Joshua', 24, 16, '&nbsp;خلقو ورته په جواب کښې ووئيل، ”مونږ به هيڅکله مالِک خُدائ نۀ پرېږدو چې د نورو معبودانو عبادت وکړُو.', NULL, '&nbsp;خلقو ورته په جواب کښې ووئيل، ”مونږ به هيڅکله مالِک خُدائ نۀ پرېږدو چې د نورو معبودانو عبادت وکړُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6026, 'Joshua 24:17', 'Joshua', 24, 17, '&nbsp;مالِک خُدائ زمونږ خُدائ پاک زمونږ پلار نيکۀ او مونږ په مِصر کښې د غلامۍ نه راوويستلو او چې هغۀ کومې معجزې کولې نو هغه مو وليدلې. چې مونږ د هر يو قوم نه هم تېرېدو او هر ځائ له هم تلو نو هغۀ مونږ په حِفاظت کښې ساتلو.', NULL, '&nbsp;مالِک خُدائ زمونږ خُدائ پاک زمونږ پلار نيکۀ او مونږ په مِصر کښې د غلامۍ نه راوويستلو او چې هغۀ کومې معجزې کولې نو هغه مو وليدلې. چې مونږ د هر يو قوم نه هم تېرېدو او هر ځائ له هم تلو نو هغۀ مونږ په حِفاظت کښې ساتلو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6027, 'Joshua 24:18', 'Joshua', 24, 18, '&nbsp;کله چې مونږ دې مُلک ته مخ په وړاندې تلو، نو مالِک خُدائ هغه ټول اموريان وشړل کوم چې دلته اوسېدل. نو ځکه مونږ به هم د مالِک خُدائ خِدمت کوُو، هغه زمونږ خُدائ پاک دے.“', NULL, '&nbsp;کله چې مونږ دې مُلک ته مخ په وړاندې تلو، نو مالِک خُدائ هغه ټول اموريان وشړل کوم چې دلته اوسېدل. نو ځکه مونږ به هم د مالِک خُدائ خِدمت کوُو، هغه زمونږ خُدائ پاک دے.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6028, 'Joshua 24:19', 'Joshua', 24, 19, '&nbsp;يشوَع خلقو ته وفرمائيل، ”خو کېدے شى چې تاسو د دې قابل نۀ شئ چې د مالِک خُدائ خِدمت وکړئ. هغه يو مقدس او غيرتى خُدائ پاک دے او هغه به ستاسو ګناهونه نۀ معاف کوى،', NULL, '&nbsp;يشوَع خلقو ته وفرمائيل، ”خو کېدے شى چې تاسو د دې قابل نۀ شئ چې د مالِک خُدائ خِدمت وکړئ. هغه يو مقدس او غيرتى خُدائ پاک دے او هغه به ستاسو ګناهونه نۀ معاف کوى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6029, 'Joshua 24:20', 'Joshua', 24, 20, '&nbsp;او کۀ تاسو هغه پرېږدئ او د پردو معبودانو خِدمت وکړئ، نو هغه به ستاسو خِلاف شى او تاسو له به سزا درکړى. هغه به تاسو تباه کړى، اګر چې هغه ستاسو سره مخکښې ښۀ هم وو.“', NULL, '&nbsp;او کۀ تاسو هغه پرېږدئ او د پردو معبودانو خِدمت وکړئ، نو هغه به ستاسو خِلاف شى او تاسو له به سزا درکړى. هغه به تاسو تباه کړى، اګر چې هغه ستاسو سره مخکښې ښۀ هم وو.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
