(6041, 'Joshua 24:32', 'Joshua', 24, 32, '&nbsp;بنى اِسرائيلو چې د مِصر نه د يوسف کوم هډُوکى راوړى وُو نو هغوئ هغه د شِکم په هغه زمکه کښې ښخ کړل کومه چې يعقوب د شِکم د پلار د همور د زامنو نه د سپينو زرو په سلو سيکو باندې اخستې وه. دا هغه زمکه وه چې د يوسف د اولاد په ذريعه ميراث شوې وه.', NULL, '&nbsp;بنى اِسرائيلو چې د مِصر نه د يوسف کوم هډُوکى راوړى وُو نو هغوئ هغه د شِکم په هغه زمکه کښې ښخ کړل کومه چې يعقوب د شِکم د پلار د همور د زامنو نه د سپينو زرو په سلو سيکو باندې اخستې وه. دا هغه زمکه وه چې د يوسف د اولاد په ذريعه ميراث شوې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
