(6049, 'Judges 1:7', 'Judges', 1, 7, '&nbsp;ادونى‌بزق ووئيل، ”اويا داسې بادشاهانو زما د دسترخوان نه پاتې شوې ټُکړې راټولې کړې دى چې د هغوئ د لاسونو او د پښو غټې ګوتې پرې کړے شوې وې. اوس خُدائ پاک ما سره هم هغه شان وکړل لکه څنګه چې ما د هغوئ سره کړى وُو.“ هغه يروشلم ته بوتلے شو، چرته چې هغه مړ شو.', NULL, '&nbsp;ادونى‌بزق ووئيل، ”اويا داسې بادشاهانو زما د دسترخوان نه پاتې شوې ټُکړې راټولې کړې دى چې د هغوئ د لاسونو او د پښو غټې ګوتې پرې کړے شوې وې. اوس خُدائ پاک ما سره هم هغه شان وکړل لکه څنګه چې ما د هغوئ سره کړى وُو.“ هغه يروشلم ته بوتلے شو، چرته چې هغه مړ شو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6050, 'Judges 1:8', 'Judges', 1, 8, '&nbsp;د يهوداه سړو په يروشلم حمله وکړه او قبضه يې کړو. هغوئ د دې خلق ووژل او په ښار يې اور ولګولو.', NULL, '&nbsp;د يهوداه سړو په يروشلم حمله وکړه او قبضه يې کړو. هغوئ د دې خلق ووژل او په ښار يې اور ولګولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6051, 'Judges 1:9', 'Judges', 1, 9, '&nbsp;د دې نه پس هغوئ روان وُو چې کنعانيانو سره جنګ وکړى چې هغوئ د غرونو په مُلک، جنوبى اوچه برخه او لاندې علاقو کښې اوسېدل.', NULL, '&nbsp;د دې نه پس هغوئ روان وُو چې کنعانيانو سره جنګ وکړى چې هغوئ د غرونو په مُلک، جنوبى اوچه برخه او لاندې علاقو کښې اوسېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
