(6056, 'Judges 1:14', 'Judges', 1, 14, '&nbsp;د وادۀ په ورځ عکسې عتنى‌اېل ته منت وکړو چې د هغې د پلار نه يو پټے وغواړى. هغه د خپل خر نه کوزه شوه او کالب ترې نه تپوس وکړو، ”تۀ څۀ غواړې؟“', NULL, '&nbsp;د وادۀ په ورځ عکسې عتنى‌اېل ته منت وکړو چې د هغې د پلار نه يو پټے وغواړى. هغه د خپل خر نه کوزه شوه او کالب ترې نه تپوس وکړو، ”تۀ څۀ غواړې؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
