(6066, 'Judges 1:26', 'Judges', 1, 26, '&nbsp;وروستو دا سړے د حِتيانو مُلک ته لاړو، هلته يې يو ښار جوړ کړو او په دې باندې يې لوز نوم کېښودو، تر اوسه پورې يې هم دغه نوم دے.', NULL, '&nbsp;وروستو دا سړے د حِتيانو مُلک ته لاړو، هلته يې يو ښار جوړ کړو او په دې باندې يې لوز نوم کېښودو، تر اوسه پورې يې هم دغه نوم دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6067, 'Judges 1:27', 'Judges', 1, 27, '&nbsp;د منسى قبيلې هغه خلق ونۀ شړل چې کوم د بيت‌شان، تعنک، دور، ابليعام، مِجدو او په ګېرچاپېره کلو کښې اوسېدل، او کنعانيان هم هلته دېره وُو.', NULL, '&nbsp;د منسى قبيلې هغه خلق ونۀ شړل چې کوم د بيت‌شان، تعنک، دور، ابليعام، مِجدو او په ګېرچاپېره کلو کښې اوسېدل، او کنعانيان هم هلته دېره وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6068, 'Judges 1:28', 'Judges', 1, 28, '&nbsp;کله چې بنى اِسرائيليان طاقتور شول، نو هغوئ کنعانيان دې ته مجبور کړل چې د هغوئ دپاره کار کوى، خو بيا يې هم هغوئ ټول ونۀ شړل.', NULL, '&nbsp;کله چې بنى اِسرائيليان طاقتور شول، نو هغوئ کنعانيان دې ته مجبور کړل چې د هغوئ دپاره کار کوى، خو بيا يې هم هغوئ ټول ونۀ شړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6069, 'Judges 1:29', 'Judges', 1, 29, '&nbsp;د اِفرائيم قبيلې هغه کنعانيان ونۀ شړل چې د جزر په ښار کښې اوسېدل، نو کنعانيان هم هلته د هغوئ سره اوسېدل.', NULL, '&nbsp;د اِفرائيم قبيلې هغه کنعانيان ونۀ شړل چې د جزر په ښار کښې اوسېدل، نو کنعانيان هم هلته د هغوئ سره اوسېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6070, 'Judges 1:30', 'Judges', 1, 30, '&nbsp;د زبولون قبيلې هغه خلق ونۀ شړل کوم چې د قِطرون او نهلال په ښارونو کښې اوسېدل، نو کنعانيان هم هلته د هغوئ سره اوسېدل او دې ته مجبور وُو چې د هغوئ دپاره کار کوى.', NULL, '&nbsp;د زبولون قبيلې هغه خلق ونۀ شړل کوم چې د قِطرون او نهلال په ښارونو کښې اوسېدل، نو کنعانيان هم هلته د هغوئ سره اوسېدل او دې ته مجبور وُو چې د هغوئ دپاره کار کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6071, 'Judges 1:31', 'Judges', 1, 31, '&nbsp;د آشر قبيلې هغه خلق ونۀ شړل کوم چې د عکو، صيدا، احلاب، اکزيب، حلبه، افيق، رِحوب په ښارونو کښې اوسېدل.', NULL, '&nbsp;د آشر قبيلې هغه خلق ونۀ شړل کوم چې د عکو، صيدا، احلاب، اکزيب، حلبه، افيق، رِحوب په ښارونو کښې اوسېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6072, 'Judges 1:32', 'Judges', 1, 32, '&nbsp;د آشر قبيلې خلق د هغه ځائ د کنعانيانو سره اوسېدل، ځکه چې هغوئ کنعانيان ونۀ شړل.', NULL, '&nbsp;د آشر قبيلې خلق د هغه ځائ د کنعانيانو سره اوسېدل، ځکه چې هغوئ کنعانيان ونۀ شړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6073, 'Judges 1:33', 'Judges', 1, 33, '&nbsp;د نفتالى قبيلې هغه خلق ونۀ شړل کوم چې د بيت‌شمس او بيت‌عنات په ښارونو کښې اوسېدل. د نفتالى خلق د هغه ځائ د کنعانيانو سره اوسېدل، خو هغوئ يې دې ته مجبور کړل چې د هغوئ دپاره کار کوى.', NULL, '&nbsp;د نفتالى قبيلې هغه خلق ونۀ شړل کوم چې د بيت‌شمس او بيت‌عنات په ښارونو کښې اوسېدل. د نفتالى خلق د هغه ځائ د کنعانيانو سره اوسېدل، خو هغوئ يې دې ته مجبور کړل چې د هغوئ دپاره کار کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6074, 'Judges 1:34', 'Judges', 1, 34, '&nbsp;اموريانو د دان قبيلې خلق مجبور کړل چې د غرونو مُلک ته لاړ شى او هغوئ يې دې ته نۀ پرېښودل چې لاندې مېدان ته لاړ شى.', NULL, '&nbsp;اموريانو د دان قبيلې خلق مجبور کړل چې د غرونو مُلک ته لاړ شى او هغوئ يې دې ته نۀ پرېښودل چې لاندې مېدان ته لاړ شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6075, 'Judges 1:35', 'Judges', 1, 35, '&nbsp;اموريان په ايالون، سعلبيم، او د حِرس په غرۀ کښې دېره وُو، خو د اِفرائيم او منسى قبيلې طاقتورې شوې او د هغوئ نه يې په زور کار اخستو.', NULL, '&nbsp;اموريان په ايالون، سعلبيم، او د حِرس په غرۀ کښې دېره وُو، خو د اِفرائيم او منسى قبيلې طاقتورې شوې او د هغوئ نه يې په زور کار اخستو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6076, 'Judges 1:36', 'Judges', 1, 36, '&nbsp;د اموريانو د حد پوله د لړم درې نه واخله تر سلع پورې او د دې نه اخوا هم وه.', NULL, '&nbsp;د اموريانو د حد پوله د لړم درې نه واخله تر سلع پورې او د دې نه اخوا هم وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6077, 'Judges 2:1', 'Judges', 2, 1, '&nbsp;د مالِک خُدائ فرښته د جِلجال نه بوکيم ته لاړه او بنى اِسرائيلو ته يې وفرمائيل، ”ما تاسو د مِصر نه راوويستلئ او هغه مُلک ته مې راوستلئ چې ستاسو د پلار نيکۀ سره ما د هغې وعده کړې ده. ما وفرمائيل زۀ به هيڅکله ستاسو سره خپل لوظ مات نۀ کړم.', NULL, '&nbsp;د مالِک خُدائ فرښته د جِلجال نه بوکيم ته لاړه او بنى اِسرائيلو ته يې وفرمائيل، ”ما تاسو د مِصر نه راوويستلئ او هغه مُلک ته مې راوستلئ چې ستاسو د پلار نيکۀ سره ما د هغې وعده کړې ده. ما وفرمائيل زۀ به هيڅکله ستاسو سره خپل لوظ مات نۀ کړم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6078, 'Judges 2:2', 'Judges', 2, 2, '&nbsp;تاسو چې د هغه خلقو سره هيڅ لوظ ونۀ کړئ کوم چې په دې مُلک کښې اوسيږى بلکې د هغوئ د قربانۍ ځايونه راوغورزوئ. خو تاسو زما د حُکم نافرمانى کړې ده. تاسو داسې ولې کړى دى؟', NULL, '&nbsp;تاسو چې د هغه خلقو سره هيڅ لوظ ونۀ کړئ کوم چې په دې مُلک کښې اوسيږى بلکې د هغوئ د قربانۍ ځايونه راوغورزوئ. خو تاسو زما د حُکم نافرمانى کړې ده. تاسو داسې ولې کړى دى؟', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6079, 'Judges 2:3', 'Judges', 2, 3, '&nbsp;اوس زۀ تاسو ته وايم چې تاسو مخ په وړاندې ځئ نو زۀ به دا خلق نۀ شړم. هغوئ به ستاسو دشمنان شى او د هغوئ معبودان به ستاسو دپاره يو دام جوړ شى.“', NULL, '&nbsp;اوس زۀ تاسو ته وايم چې تاسو مخ په وړاندې ځئ نو زۀ به دا خلق نۀ شړم. هغوئ به ستاسو دشمنان شى او د هغوئ معبودان به ستاسو دپاره يو دام جوړ شى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6080, 'Judges 2:4', 'Judges', 2, 4, '&nbsp;کله چې د مالِک خُدائ فرښتې دا خبرې بنى اِسرائيلو ته وکړې نو ټول قوم په چغو چغو وژړل،', NULL, '&nbsp;کله چې د مالِک خُدائ فرښتې دا خبرې بنى اِسرائيلو ته وکړې نو ټول قوم په چغو چغو وژړل،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6081, 'Judges 2:5', 'Judges', 2, 5, '&nbsp;نو ځکه په هغه ځائ يې بوکيم نوم کېښودو چې مطلب يې ژړا دے او هلته هغوئ مالِک خُدائ ته قربانۍ پېش کړې.', NULL, '&nbsp;نو ځکه په هغه ځائ يې بوکيم نوم کېښودو چې مطلب يې ژړا دے او هلته هغوئ مالِک خُدائ ته قربانۍ پېش کړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6082, 'Judges 2:6', 'Judges', 2, 6, '&nbsp;يشوَع چې کله بنى اِسرائيل رُخصت کړل، نو هره يوه قبيله لاړله چې د هغه مُلک خپله خپله برخه ونيسى.', NULL, '&nbsp;يشوَع چې کله بنى اِسرائيل رُخصت کړل، نو هره يوه قبيله لاړله چې د هغه مُلک خپله خپله برخه ونيسى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6083, 'Judges 2:7', 'Judges', 2, 7, '&nbsp;تر کومې پورې چې يشوَع ژوندے وو، نو بنى اِسرائيلو د مالِک خُدائ خِدمت کولو او د هغۀ د مرګ نه پس چې تر کومې پورې هغه مشران ژوندى وُو چې هغوئ په خپله هغه ټول لوئ کارونه ليدلى وُو چې مالِک خُدائ د بنى اِسرائيلو دپاره کړى وُو، نو هغوئ هم هغه شان کول.', NULL, '&nbsp;تر کومې پورې چې يشوَع ژوندے وو، نو بنى اِسرائيلو د مالِک خُدائ خِدمت کولو او د هغۀ د مرګ نه پس چې تر کومې پورې هغه مشران ژوندى وُو چې هغوئ په خپله هغه ټول لوئ کارونه ليدلى وُو چې مالِک خُدائ د بنى اِسرائيلو دپاره کړى وُو، نو هغوئ هم هغه شان کول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6084, 'Judges 2:8', 'Judges', 2, 8, '&nbsp;د مالِک خُدائ خِدمت کوونکے د نون زوئ يشوَع د يو سل او لسو کالو په عُمر کښې مړ شو.', NULL, '&nbsp;د مالِک خُدائ خِدمت کوونکے د نون زوئ يشوَع د يو سل او لسو کالو په عُمر کښې مړ شو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6085, 'Judges 2:9', 'Judges', 2, 9, '&nbsp;هغه په خپله زمکه کښې ښخ کړے شو، هغه ځائ د جعس په شمالى طرف د اِفرائيم غرونو په مُلک تمنت‌حِرس کښې وو.', NULL, '&nbsp;هغه په خپله زمکه کښې ښخ کړے شو، هغه ځائ د جعس په شمالى طرف د اِفرائيم غرونو په مُلک تمنت‌حِرس کښې وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6086, 'Judges 2:10', 'Judges', 2, 10, '&nbsp;هغه ټول نسل هم مړ شو او ورپسې نسل مالِک خُدائ او هغه څۀ هېر کړل چې مالِک خُدائ د بنى اِسرائيلو دپاره کړى وُو.', NULL, '&nbsp;هغه ټول نسل هم مړ شو او ورپسې نسل مالِک خُدائ او هغه څۀ هېر کړل چې مالِک خُدائ د بنى اِسرائيلو دپاره کړى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6087, 'Judges 2:11', 'Judges', 2, 11, '&nbsp;نو بنى اِسرائيلو د مالِک خُدائ خِلاف ګناه وکړه او د بعل د بُتانو عبادت يې شروع کړو.', NULL, '&nbsp;نو بنى اِسرائيلو د مالِک خُدائ خِلاف ګناه وکړه او د بعل د بُتانو عبادت يې شروع کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6088, 'Judges 2:12', 'Judges', 2, 12, '&nbsp;هغوئ د مالِک خُدائ عبادت پرېښودو، کوم چې د هغوئ د پلار نيکۀ خُدائ پاک وو، هغه خُدائ پاک چې هغوئ يې د مِصر د مُلک نه راويستلى وُو او هغوئ د نورو معبودانو عبادت شروع کړو، د هغه خلقو د معبودانو چې د هغوئ په خواوشا کښې اوسېدل، هغوئ ورته سجدې وکړې او مالِک خُدائ يې په غصه کړو.', NULL, '&nbsp;هغوئ د مالِک خُدائ عبادت پرېښودو، کوم چې د هغوئ د پلار نيکۀ خُدائ پاک وو، هغه خُدائ پاک چې هغوئ يې د مِصر د مُلک نه راويستلى وُو او هغوئ د نورو معبودانو عبادت شروع کړو، د هغه خلقو د معبودانو چې د هغوئ په خواوشا کښې اوسېدل، هغوئ ورته سجدې وکړې او مالِک خُدائ يې په غصه کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6089, 'Judges 2:13', 'Judges', 2, 13, '&nbsp;هغوئ د مالِک خُدائ عبادت پرېښودو او د بعل او عستارات خِدمت يې شروع کړو.', NULL, '&nbsp;هغوئ د مالِک خُدائ عبادت پرېښودو او د بعل او عستارات خِدمت يې شروع کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6090, 'Judges 2:14', 'Judges', 2, 14, '&nbsp;نو مالِک خُدائ بنى اِسرائيلو ته سخت غصه شو او هغوئ يې ډاکوانو ته حواله کړل او ډاکوانو هغوئ لوټ کړل. هغۀ په هغوئ باندې ټول د خوا او شا دشمنان غالِب کړل، نو هغوئ نور د دې جوګه نۀ وُو چې خپلو دشمنانو ته ټينګ شى.', NULL, '&nbsp;نو مالِک خُدائ بنى اِسرائيلو ته سخت غصه شو او هغوئ يې ډاکوانو ته حواله کړل او ډاکوانو هغوئ لوټ کړل. هغۀ په هغوئ باندې ټول د خوا او شا دشمنان غالِب کړل، نو هغوئ نور د دې جوګه نۀ وُو چې خپلو دشمنانو ته ټينګ شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6091, 'Judges 2:15', 'Judges', 2, 15, '&nbsp;هر ځل چې هغوئ جنګ له تلل، نو مالِک خُدائ به د هغوئ خِلاف وو او هغوئ به يې د شکست سره مخ کول، لکه څنګه چې هغۀ فرمائيلى وُو چې هغه به هم داسې وى. هغوئ په سخت کړاؤ کښې راګېر وُو.', NULL, '&nbsp;هر ځل چې هغوئ جنګ له تلل، نو مالِک خُدائ به د هغوئ خِلاف وو او هغوئ به يې د شکست سره مخ کول، لکه څنګه چې هغۀ فرمائيلى وُو چې هغه به هم داسې وى. هغوئ په سخت کړاؤ کښې راګېر وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6092, 'Judges 2:16', 'Judges', 2, 16, '&nbsp;بيا مالِک خُدائ په بنى اِسرائيلو باندې قاضيان مقرر کړل او دې قاضيانو د ډاکوانو نه خلاص کړل.', NULL, '&nbsp;بيا مالِک خُدائ په بنى اِسرائيلو باندې قاضيان مقرر کړل او دې قاضيانو د ډاکوانو نه خلاص کړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6093, 'Judges 2:17', 'Judges', 2, 17, '&nbsp;خو بنى اِسرائيلو خپلو قاضيانو ته غوږ ونۀ نيولو. بنى اِسرائيلو د مالِک خُدائ سره بې‌غېرتى وکړه او د نورو معبودانو عبادت يې وکړو. هغوئ زر د هغې لارې نه واوړېدل چې په کومه د هغوئ پلار نيکۀ روان وُو، چې هغوئ په فرمانبردارۍ سره د مالِک خُدائ د حُکم په مطابق روان وُو.', NULL, '&nbsp;خو بنى اِسرائيلو خپلو قاضيانو ته غوږ ونۀ نيولو. بنى اِسرائيلو د مالِک خُدائ سره بې‌غېرتى وکړه او د نورو معبودانو عبادت يې وکړو. هغوئ زر د هغې لارې نه واوړېدل چې په کومه د هغوئ پلار نيکۀ روان وُو، چې هغوئ په فرمانبردارۍ سره د مالِک خُدائ د حُکم په مطابق روان وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6094, 'Judges 2:18', 'Judges', 2, 18, '&nbsp;کله هم چې مالِک خُدائ بنى اِسرائيلو له يو قاضى ورکړو، نو مالِک خُدائ به د هغه قاضى مل وو او خلق به يې د خپلو دشمنانو نه بچ کول چې تر کومې به هغه قاضى ژوندے وو. نو مالِک خُدائ به په هغوئ رحم کولو ځکه هغوئ د خپلو تکليفونو او مصيبتونو لاندې فرياد کولو.', NULL, '&nbsp;کله هم چې مالِک خُدائ بنى اِسرائيلو له يو قاضى ورکړو، نو مالِک خُدائ به د هغه قاضى مل وو او خلق به يې د خپلو دشمنانو نه بچ کول چې تر کومې به هغه قاضى ژوندے وو. نو مالِک خُدائ به په هغوئ رحم کولو ځکه هغوئ د خپلو تکليفونو او مصيبتونو لاندې فرياد کولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6095, 'Judges 2:19', 'Judges', 2, 19, '&nbsp;خو چې کله به قاضى مړ شو، نو خلق به هم هغه ناولو کارونو ته وروګرځېدل او د مخکښېنى نسل نه به يې بدتر عمل کولو. هغوئ به د نورو معبودانو خِدمت او عبادت کولو او د خپلو بدو عملونو او خپلو ضدى طريقو پرېښودو نه به يې اِنکار کولو.', NULL, '&nbsp;خو چې کله به قاضى مړ شو، نو خلق به هم هغه ناولو کارونو ته وروګرځېدل او د مخکښېنى نسل نه به يې بدتر عمل کولو. هغوئ به د نورو معبودانو خِدمت او عبادت کولو او د خپلو بدو عملونو او خپلو ضدى طريقو پرېښودو نه به يې اِنکار کولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6096, 'Judges 2:20', 'Judges', 2, 20, '&nbsp;نو مالِک خُدائ به بنى اِسرائيلو ته سخت په قهر شو او وبه يې فرمائيل، ”دې نسل هغه لوظ مات کړے دے چې ما يې د دوئ پلار نيکۀ له د پوره کولو حُکم ورکړے وو. ځکه چې دوئ زما نافرمانى کړې ده،', NULL, '&nbsp;نو مالِک خُدائ به بنى اِسرائيلو ته سخت په قهر شو او وبه يې فرمائيل، ”دې نسل هغه لوظ مات کړے دے چې ما يې د دوئ پلار نيکۀ له د پوره کولو حُکم ورکړے وو. ځکه چې دوئ زما نافرمانى کړې ده،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6097, 'Judges 2:21', 'Judges', 2, 21, '&nbsp;د يشوَع د مرګ په وخت چې په هغه مُلک کښې کوم قومونه پاتې وُو نو زۀ به هغوئ نور نۀ شړم.', NULL, '&nbsp;د يشوَع د مرګ په وخت چې په هغه مُلک کښې کوم قومونه پاتې وُو نو زۀ به هغوئ نور نۀ شړم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6098, 'Judges 2:22', 'Judges', 2, 22, '&nbsp;زۀ به هغوئ د دې دپاره استعمال کړم چې دا معلومه کړم چې دا بنى اِسرائيليان د خپل پلار نيکۀ په شان زما په لاره روان دى او کۀ نه.“', NULL, '&nbsp;زۀ به هغوئ د دې دپاره استعمال کړم چې دا معلومه کړم چې دا بنى اِسرائيليان د خپل پلار نيکۀ په شان زما په لاره روان دى او کۀ نه.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6099, 'Judges 2:23', 'Judges', 2, 23, '&nbsp;نو مالِک خُدائ هغه قومونه پرېښودل چې په هغه مُلک کښې پاتې شى، هغۀ نۀ يشوَع له په هغوئ باندې فتح ورکړه او نۀ يې د يشوَع د مرګ نه پس زر هغوئ وشړل.', NULL, '&nbsp;نو مالِک خُدائ هغه قومونه پرېښودل چې په هغه مُلک کښې پاتې شى، هغۀ نۀ يشوَع له په هغوئ باندې فتح ورکړه او نۀ يې د يشوَع د مرګ نه پس زر هغوئ وشړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
