(6102, 'Judges 3:3', 'Judges', 3, 3, '&nbsp;په هغه مُلک کښې پينځۀ فلستى ښارونه پاتې شول، ټول کنعانيان، صيدانيان او حِويان چې د بعل حرمون غر نه واخله د حمات درې پورې د لبنان په غرونو کښې اوسېدل.', NULL, '&nbsp;په هغه مُلک کښې پينځۀ فلستى ښارونه پاتې شول، ټول کنعانيان، صيدانيان او حِويان چې د بعل حرمون غر نه واخله د حمات درې پورې د لبنان په غرونو کښې اوسېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
