(6117, 'Judges 3:18', 'Judges', 3, 18, '&nbsp;کله چې اهُود هغۀ له محصُول ورکړو، چې کومو سړو دا راوړے وو نو هغوئ يې رُخصت کړل.', NULL, '&nbsp;کله چې اهُود هغۀ له محصُول ورکړو، چې کومو سړو دا راوړے وو نو هغوئ يې رُخصت کړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6118, 'Judges 3:19', 'Judges', 3, 19, '&nbsp;خو چې کله اهُود د کاڼو بُتانو ته ورسېدو چې جِلجال ته نزدې وو، نو عجلون ته راواپس شو او ورته يې ووئيل، ”بادشاه سلامت، زما سره ستا دپاره يو د راز خبره ده.“ نو بادشاه ورته ووئيل، ”اوس خبره مۀ کوه.“ او د هغۀ ټول نوکران د هغۀ د حضور نه لاړل.', NULL, '&nbsp;خو چې کله اهُود د کاڼو بُتانو ته ورسېدو چې جِلجال ته نزدې وو، نو عجلون ته راواپس شو او ورته يې ووئيل، ”بادشاه سلامت، زما سره ستا دپاره يو د راز خبره ده.“ نو بادشاه ورته ووئيل، ”اوس خبره مۀ کوه.“ او د هغۀ ټول نوکران د هغۀ د حضور نه لاړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6119, 'Judges 3:20', 'Judges', 3, 20, '&nbsp;بيا چې کله بادشاه په چت باندې په خپله يخه کوټه کښې ناست وو، اهُود هغۀ له ورَغلو او ورته يې ووئيل، ”زما سره ستا دپاره د خُدائ پاک نه يو پېغام دے.“ نو بادشاه د تخت نه پاڅېدو.', NULL, '&nbsp;بيا چې کله بادشاه په چت باندې په خپله يخه کوټه کښې ناست وو، اهُود هغۀ له ورَغلو او ورته يې ووئيل، ”زما سره ستا دپاره د خُدائ پاک نه يو پېغام دے.“ نو بادشاه د تخت نه پاڅېدو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6120, 'Judges 3:21', 'Judges', 3, 21, '&nbsp;اهُود د خپل ګس لاس سره د ښى طرف نه تُوره راوويسته او د بادشاه په خېټه کښې يې ننه ويستله.', NULL, '&nbsp;اهُود د خپل ګس لاس سره د ښى طرف نه تُوره راوويسته او د بادشاه په خېټه کښې يې ننه ويستله.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
