(6122, 'Judges 3:23', 'Judges', 3, 23, '&nbsp;بيا اهُود برنډې ته ووتلو، هغۀ پسې يې دروازې بندې کړې او تالې يې ولګولې،', NULL, '&nbsp;بيا اهُود برنډې ته ووتلو، هغۀ پسې يې دروازې بندې کړې او تالې يې ولګولې،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6123, 'Judges 3:24', 'Judges', 3, 24, '&nbsp;او ترې نه لاړو. نوکران راغلل او وې ليدل چې دروازې تاله وې، هغوئ صِرف دا خيال کولو چې بادشاه دننه دے او متيازې کوى.', NULL, '&nbsp;او ترې نه لاړو. نوکران راغلل او وې ليدل چې دروازې تاله وې، هغوئ صِرف دا خيال کولو چې بادشاه دننه دے او متيازې کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6124, 'Judges 3:25', 'Judges', 3, 25, '&nbsp;هغوئ تر څۀ وخته پورې انتظار وکړو، خو چې هغۀ بيا هم دروازه کولاو نۀ کړه، نو هغوئ چابى واخستله او دا يې کولاو کړه. او د هغوئ نېک دننه په فرش باندې مړ پروت وو.', NULL, '&nbsp;هغوئ تر څۀ وخته پورې انتظار وکړو، خو چې هغۀ بيا هم دروازه کولاو نۀ کړه، نو هغوئ چابى واخستله او دا يې کولاو کړه. او د هغوئ نېک دننه په فرش باندې مړ پروت وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
