(6164, 'Judges 5:10', 'Judges', 5, 10, '&nbsp;ووايئ تاسو چې په سپينو خرونو باندې سورلى کوئ، او تاسو په ښو قالينونو باندې کښېنئ، او تاسو په لاره باندې پېدل مزل کوئ.', NULL, '&nbsp;ووايئ تاسو چې په سپينو خرونو باندې سورلى کوئ، او تاسو په ښو قالينونو باندې کښېنئ، او تاسو په لاره باندې پېدل مزل کوئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6165, 'Judges 5:11', 'Judges', 5, 11, '&nbsp;د اوبو په ګودرو کښې د سندرغاړو آواز واورئ. هغوئ د مالِک خُدائ فتحې بيانوى، چې د بنى اِسرائيلو فتحې دى. بيا د مالِک خُدائ خلق د ښار د دروازو طرف ته روان شول.', NULL, '&nbsp;د اوبو په ګودرو کښې د سندرغاړو آواز واورئ. هغوئ د مالِک خُدائ فتحې بيانوى، چې د بنى اِسرائيلو فتحې دى. بيا د مالِک خُدائ خلق د ښار د دروازو طرف ته روان شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6166, 'Judges 5:12', 'Judges', 5, 12, '&nbsp;پاڅه، پاڅه. دبورې، پاڅه او يوه سندره ووايه، د ابى‌نوعم زويه برقه، پاڅه، خپل قېديان روان کړه.', NULL, '&nbsp;پاڅه، پاڅه. دبورې، پاڅه او يوه سندره ووايه، د ابى‌نوعم زويه برقه، پاڅه، خپل قېديان روان کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6167, 'Judges 5:13', 'Judges', 5, 13, '&nbsp;بيا پاتې شوى مشران راکوز شول، د مالِک خُدائ خلق د طاقتورو خِلاف راکوز شول.', NULL, '&nbsp;بيا پاتې شوى مشران راکوز شول، د مالِک خُدائ خلق د طاقتورو خِلاف راکوز شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6168, 'Judges 5:14', 'Judges', 5, 14, '&nbsp;هغوئ د اِفرائيم نه مېدان ته راغلل، د بنيامين په قبيله او د هغوئ په خلقو پسې. مشران د مکير نه راکوز شول، او آفسران د زبولون نه.', NULL, '&nbsp;هغوئ د اِفرائيم نه مېدان ته راغلل، د بنيامين په قبيله او د هغوئ په خلقو پسې. مشران د مکير نه راکوز شول، او آفسران د زبولون نه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6169, 'Judges 5:15', 'Judges', 5, 15, '&nbsp;د يساکار مشران د دبورې سره راغلل، يساکار او برق هم راغلل، او هغوئ په مېدان کښې په هغۀ پسې روان وُو. خو د روبين قبيله شش او پنج کښې شوه، هغوئ دا فېصله ونۀ کړے شوه چې راشى.', NULL, '&nbsp;د يساکار مشران د دبورې سره راغلل، يساکار او برق هم راغلل، او هغوئ په مېدان کښې په هغۀ پسې روان وُو. خو د روبين قبيله شش او پنج کښې شوه، هغوئ دا فېصله ونۀ کړے شوه چې راشى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6170, 'Judges 5:16', 'Judges', 5, 16, '&nbsp;هغوئ ولې د ګډو سره وروستو پاتې شول؟ چې شپانو ته غوږ ونيسى چې رَمو ته آوازونه کوى؟ آو، د روبين قبيله شش او پنج کښې شوه، هغوئ دا فېصله ونۀ کړے شوه چې راشى.', NULL, '&nbsp;هغوئ ولې د ګډو سره وروستو پاتې شول؟ چې شپانو ته غوږ ونيسى چې رَمو ته آوازونه کوى؟ آو، د روبين قبيله شش او پنج کښې شوه، هغوئ دا فېصله ونۀ کړے شوه چې راشى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6171, 'Judges 5:17', 'Judges', 5, 17, '&nbsp;د جاد قبيله د اُردن نمرخاتۀ طرف ته پاتې شوه، او د دان قبيله د سمندرى جهازونو سره ولې پاتې شوه؟ د آشر قبيله د سمندر په غاړه پاتې شوه، هغوئ د سمندر په غاړه پاتې شول.', NULL, '&nbsp;د جاد قبيله د اُردن نمرخاتۀ طرف ته پاتې شوه، او د دان قبيله د سمندرى جهازونو سره ولې پاتې شوه؟ د آشر قبيله د سمندر په غاړه پاتې شوه، هغوئ د سمندر په غاړه پاتې شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6172, 'Judges 5:18', 'Judges', 5, 18, '&nbsp;خو د زبولون او نفتالى خلقو خپل ژوند د جنګ مېدان په خطره کښې واچولو.', NULL, '&nbsp;خو د زبولون او نفتالى خلقو خپل ژوند د جنګ مېدان په خطره کښې واچولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6173, 'Judges 5:19', 'Judges', 5, 19, '&nbsp;په تعنک کښې، د مِجدو نِهر سره، بادشاهان راغلل او هغوئ جنګ وکړو، د کنعان بادشاهانو جنګ وکړو، خو هغوئ سپين زر لوټ نۀ کړل.', NULL, '&nbsp;په تعنک کښې، د مِجدو نِهر سره، بادشاهان راغلل او هغوئ جنګ وکړو، د کنعان بادشاهانو جنګ وکړو، خو هغوئ سپين زر لوټ نۀ کړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6174, 'Judges 5:20', 'Judges', 5, 20, '&nbsp;د آسمان نه ستورو جګړه کوله، څنګه چې هغوئ په آسمان کښې حرکت کولو، ستورو د سِسيرا خِلاف جګړه وکړه.', NULL, '&nbsp;د آسمان نه ستورو جګړه کوله، څنګه چې هغوئ په آسمان کښې حرکت کولو، ستورو د سِسيرا خِلاف جګړه وکړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6175, 'Judges 5:21', 'Judges', 5, 21, '&nbsp;په قيسون کښې يو سېلاب هغوئ يوړل د قيسون تېز درياب هغوئ په مخه کړل. زۀ به روان شم او د طاقت سره به روان يم.', NULL, '&nbsp;په قيسون کښې يو سېلاب هغوئ يوړل د قيسون تېز درياب هغوئ په مخه کړل. زۀ به روان شم او د طاقت سره به روان يم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6176, 'Judges 5:22', 'Judges', 5, 22, '&nbsp;بيا آسونه په منډه راغلل، او د خپلو پښو د سومونو نښې يې په زمکه باندې جوړې کړې.', NULL, '&nbsp;بيا آسونه په منډه راغلل، او د خپلو پښو د سومونو نښې يې په زمکه باندې جوړې کړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6177, 'Judges 5:23', 'Judges', 5, 23, '&nbsp;د مالِک خُدائ فرښته فرمائى، ”د ميروز په خلقو دې لعنت وى، په هغوئ دې سخت لعنت وى. ځکه چې هغوئ د مالِک خُدائ په جنګ کښې د مدد دپاره رانۀ غلل، هغوئ د تکړه جنګ کوونکو خِلاف د مالِک خُدائ مدد ونۀ کړو.“', NULL, '&nbsp;د مالِک خُدائ فرښته فرمائى، ”د ميروز په خلقو دې لعنت وى، په هغوئ دې سخت لعنت وى. ځکه چې هغوئ د مالِک خُدائ په جنګ کښې د مدد دپاره رانۀ غلل، هغوئ د تکړه جنګ کوونکو خِلاف د مالِک خُدائ مدد ونۀ کړو.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6178, 'Judges 5:24', 'Judges', 5, 24, '&nbsp;ياعيل د ټولو ښځو نه بختوره ده، چې د قينى حِبر ښځه ده، د ټولو نه بختوره ښځه چې په خېمو کښې اوسيږى.', NULL, '&nbsp;ياعيل د ټولو ښځو نه بختوره ده، چې د قينى حِبر ښځه ده، د ټولو نه بختوره ښځه چې په خېمو کښې اوسيږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6179, 'Judges 5:25', 'Judges', 5, 25, '&nbsp;سِسيراه اوبۀ وغوښتلې، خو هغې پئ ورکړل، هغې په يو ښُکلى جام کښې ورله شُملې راوړې.', NULL, '&nbsp;سِسيراه اوبۀ وغوښتلې، خو هغې پئ ورکړل، هغې په يو ښُکلى جام کښې ورله شُملې راوړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6180, 'Judges 5:26', 'Judges', 5, 26, '&nbsp;هغې په يو لاس کښې د خېمې موږے راوړو، او په بل لاس کښې د مزدور څټک، هغې سِسيرا ووهلو او د هغۀ کوپړۍ يې ماته کړه، او تندے يې ورله سورے سورے کړو.', NULL, '&nbsp;هغې په يو لاس کښې د خېمې موږے راوړو، او په بل لاس کښې د مزدور څټک، هغې سِسيرا ووهلو او د هغۀ کوپړۍ يې ماته کړه، او تندے يې ورله سورے سورے کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
