(6182, 'Judges 5:28', 'Judges', 5, 28, '&nbsp;د سِسيرا مور د کړکۍ د جالۍ نه بهر نظر واچولو، هغې تپوس وکړو، ”د هغۀ ګاډۍ ولې دومره ناوخته کړو؟ مونږ ولې د هغۀ د ګاډۍ آواز نۀ اورو؟“', NULL, '&nbsp;د سِسيرا مور د کړکۍ د جالۍ نه بهر نظر واچولو، هغې تپوس وکړو، ”د هغۀ ګاډۍ ولې دومره ناوخته کړو؟ مونږ ولې د هغۀ د ګاډۍ آواز نۀ اورو؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6183, 'Judges 5:29', 'Judges', 5, 29, '&nbsp;هوښيارو ښځو جواب ورکړو، بلکې هغې به ځان ته په خپله بيا بيا دا وئيل،', NULL, '&nbsp;هوښيارو ښځو جواب ورکړو، بلکې هغې به ځان ته په خپله بيا بيا دا وئيل،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6184, 'Judges 5:30', 'Judges', 5, 30, '&nbsp;”هغوئ لوټ شوے مال تقسيموى، د هر فوجى دپاره يوه يا دوه ښځې، د سِسيرا دپاره به رنګ شوې جامې وى، آو، هغه ښې ګُلکارى شوې ټوکړې چې زما د غاړې دپاره دى.“', NULL, '&nbsp;”هغوئ لوټ شوے مال تقسيموى، د هر فوجى دپاره يوه يا دوه ښځې، د سِسيرا دپاره به رنګ شوې جامې وى، آو، هغه ښې ګُلکارى شوې ټوکړې چې زما د غاړې دپاره دى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6185, 'Judges 5:31', 'Judges', 5, 31, '&nbsp;مالِکه خُدايه، ستا ټول دشمنان دې هم داسې مړۀ شى، خو ستا دوستان دې د خپل ټول زور سره د ختونکى نمر په شان وځليږى.“ او څلوېښت کاله په هغه مُلک کښې امن وو.', NULL, '&nbsp;مالِکه خُدايه، ستا ټول دشمنان دې هم داسې مړۀ شى، خو ستا دوستان دې د خپل ټول زور سره د ختونکى نمر په شان وځليږى.“
