(6222, 'Judges 6:37', 'Judges', 6, 37, '&nbsp;ټيک ده، زۀ به په درمند باندې دا وړۍ وغوړوم. خو کۀ په سحر کښې پرخه صِرف په وړۍ باندې وى او په زمکه باندې نۀ وى، نو ما ته به پته ولګى چې د بنى اِسرائيلو بچ کولو دپاره به تۀ ما استعمالوې.“', NULL, '&nbsp;ټيک ده، زۀ به په درمند باندې دا وړۍ وغوړوم. خو کۀ په سحر کښې پرخه صِرف په وړۍ باندې وى او په زمکه باندې نۀ وى، نو ما ته به پته ولګى چې د بنى اِسرائيلو بچ کولو دپاره به تۀ ما استعمالوې.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6223, 'Judges 6:38', 'Judges', 6, 38, '&nbsp;نو هم دغه شان وشول. کله چې جدعون ورپسې سحر وختى پاڅېدو، هغۀ وړۍ نچوړ کړه او دومره ډېره پرخه يې ترې نه وويستله چې د اوبو نه يې يو لوښے ډک شو.', NULL, '&nbsp;نو هم دغه شان وشول. کله چې جدعون ورپسې سحر وختى پاڅېدو، هغۀ وړۍ نچوړ کړه او دومره ډېره پرخه يې ترې نه وويستله چې د اوبو نه يې يو لوښے ډک شو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6224, 'Judges 6:39', 'Judges', 6, 39, '&nbsp;جدعون خُدائ پاک ته وفرمائيل، ”ما ته مۀ غصه کېږه، ما له اجازت راکړه چې صِرف يوه خبره وکړم. ما لږ پرېږده چې په وړۍ باندې يو بل آزمېښت وکړم. دا ځل پرېږده چې وړۍ اوچه وى او زمکه لمده وى.“', NULL, '&nbsp;جدعون خُدائ پاک ته وفرمائيل، ”ما ته مۀ غصه کېږه، ما له اجازت راکړه چې صِرف يوه خبره وکړم. ما لږ پرېږده چې په وړۍ باندې يو بل آزمېښت وکړم. دا ځل پرېږده چې وړۍ اوچه وى او زمکه لمده وى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
