(6227, 'Judges 7:2', 'Judges', 7, 2, '&nbsp;مالِک خُدائ جدعون ته وفرمائيل، ”تا سره چې کوم سړى دى دا زما دپاره ډېر زيات دى چې هغوئ له په ميديانيانو باندې فتح ورکړم. کېدے شى چې هغوئ دا سوچ وکړى چې هغوئ د خپل طاقت سره دا ګټه موندلې ده، نو مغروره به شى.', NULL, '&nbsp;مالِک خُدائ جدعون ته وفرمائيل، ”تا سره چې کوم سړى دى دا زما دپاره ډېر زيات دى چې هغوئ له په ميديانيانو باندې فتح ورکړم. کېدے شى چې هغوئ دا سوچ وکړى چې هغوئ د خپل طاقت سره دا ګټه موندلې ده، نو مغروره به شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6228, 'Judges 7:3', 'Judges', 7, 3, '&nbsp;خلقو ته اِعلان وکړه، هر څوک چې يرېدلې وى يا يې زړونه بائيللى وى نو هغوئ دې واپس کور ته لاړ شى او مونږ به دلته د جِلعاد د غر سره ايسار شو.“ نو دوويشت زره واپس لاړل او لس زره ايسار شول.', NULL, '&nbsp;خلقو ته اِعلان وکړه، هر څوک چې يرېدلې وى يا يې زړونه بائيللى وى نو هغوئ دې واپس کور ته لاړ شى او مونږ به دلته د جِلعاد د غر سره ايسار شو.“ نو دوويشت زره واپس لاړل او لس زره ايسار شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6229, 'Judges 7:4', 'Judges', 7, 4, '&nbsp;بيا مالِک خُدائ جدعون ته وفرمائيل، ”تا سره دا سړى اوس هم ډېر زيات دى. هغوئ لاندې اوبو ته بوځه او زۀ به هغوئ ستا دپاره هلته بېل بېل کړم. چې زۀ تا ته ووايم چې دا سړى به تا سره خامخا ځى نو هغه به ځى او چې کوم سړى درته وښايم چې نۀ به ځى نو هغه به نۀ ځى.“', NULL, '&nbsp;بيا مالِک خُدائ جدعون ته وفرمائيل، ”تا سره دا سړى اوس هم ډېر زيات دى. هغوئ لاندې اوبو ته بوځه او زۀ به هغوئ ستا دپاره هلته بېل بېل کړم. چې زۀ تا ته ووايم چې دا سړى به تا سره خامخا ځى نو هغه به ځى او چې کوم سړى درته وښايم چې نۀ به ځى نو هغه به نۀ ځى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6230, 'Judges 7:5', 'Judges', 7, 5, '&nbsp;جدعون سړى اوبو له بوتلل او مالِک خُدائ هغۀ ته وفرمائيل، ”هغه کسان چې د سپى په شان په ژبه اوبۀ څښى، د هغه ټولو نه جدا کړه چې په خپلو ګوډو باندې ټيټ شى او اوبۀ وڅښى.“', NULL, '&nbsp;جدعون سړى اوبو له بوتلل او مالِک خُدائ هغۀ ته وفرمائيل، ”هغه کسان چې د سپى په شان په ژبه اوبۀ څښى، د هغه ټولو نه جدا کړه چې په خپلو ګوډو باندې ټيټ شى او اوبۀ وڅښى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6231, 'Judges 7:6', 'Judges', 7, 6, '&nbsp;هلته درې سوه سړى داسې وُو چې هغوئ په لَپو کښې اوبۀ راواخستلې او وې څښلې، او نور ټول په خپلو ګوډو باندې ټيټ شول او اوبۀ يې وڅښلې.', NULL, '&nbsp;هلته درې سوه سړى داسې وُو چې هغوئ په لَپو کښې اوبۀ راواخستلې او وې څښلې، او نور ټول په خپلو ګوډو باندې ټيټ شول او اوبۀ يې وڅښلې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6232, 'Judges 7:7', 'Judges', 7, 7, '&nbsp;مالِک خُدائ جدعون ته وفرمائيل، ”د دې درې سوو سړو په ذريعه چې په لَپو باندې اوبۀ څښى، زۀ به تاسو بچ کړم او په ميديانيانو باندې به فتح درکړم. باقى نور ټول کورونو ته ولېږه.“', NULL, '&nbsp;مالِک خُدائ جدعون ته وفرمائيل، ”د دې درې سوو سړو په ذريعه چې په لَپو باندې اوبۀ څښى، زۀ به تاسو بچ کړم او په ميديانيانو باندې به فتح درکړم. باقى نور ټول کورونو ته ولېږه.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6233, 'Judges 7:8', 'Judges', 7, 8, '&nbsp;نو جدعون هغه ټول بنى اِسرائيليان کور ته ولېږل بغېر د هغه درېو سوو نه، چا چې بيګلې او سامان ساتلے وو. د ميديانيانو کېمپ د هغوئ نه لاندې په مېدان کښې وو.', NULL, '&nbsp;نو جدعون هغه ټول بنى اِسرائيليان کور ته ولېږل بغېر د هغه درېو سوو نه، چا چې بيګلې او سامان ساتلے وو. د ميديانيانو کېمپ د هغوئ نه لاندې په مېدان کښې وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
