(6238, 'Judges 7:13', 'Judges', 7, 13, '&nbsp;کله چې جدعون راورسېدو، هغۀ واورېدل چې يو سړے خپل ملګرى ته خوب بيانوى. هغۀ وفرمائيل، ”ما خوب وليدو چې د اوربشو يو ګول روټۍ راورغړېده او يوه خېمه يې ووهله، خېمه په بل مخ واوړېدله او راوغورزېدله.“', NULL, '&nbsp;کله چې جدعون راورسېدو، هغۀ واورېدل چې يو سړے خپل ملګرى ته خوب بيانوى. هغۀ وفرمائيل، ”ما خوب وليدو چې د اوربشو يو ګول روټۍ راورغړېده او يوه خېمه يې ووهله، خېمه په بل مخ واوړېدله او راوغورزېدله.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6239, 'Judges 7:14', 'Judges', 7, 14, '&nbsp;د هغۀ دوست جواب ورکړو، ”دا د بنى اِسرائيلو تُوره ده چې د يوآس زوئ جدعون دے، د دې بل هيڅ مطلب نشته. خُدائ پاک هغۀ له په ميديانيانو او زمونږ په ټول لښکر باندې فتح ورکړې ده.“', NULL, '&nbsp;د هغۀ دوست جواب ورکړو، ”دا د بنى اِسرائيلو تُوره ده چې د يوآس زوئ جدعون دے، د دې بل هيڅ مطلب نشته. خُدائ پاک هغۀ له په ميديانيانو او زمونږ په ټول لښکر باندې فتح ورکړې ده.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
