(6300, 'Judges 9:15', 'Judges', 9, 15, '&nbsp;د ازغو غنې جواب ورکړو چې، کۀ تاسو په رښتيا سره ما خپل بادشاه جوړول غواړئ، نو زما د سورى لاندې پناه واخلئ. کۀ تاسو داسې ونۀ کړل نو زما د ازغو څانګو نه به اور بل شى او د لبنان د دِيار ونې به وسوزوى.“', NULL, '&nbsp;د ازغو غنې جواب ورکړو چې، کۀ تاسو په رښتيا سره ما خپل بادشاه جوړول غواړئ، نو زما د سورى لاندې پناه واخلئ. کۀ تاسو داسې ونۀ کړل نو زما د ازغو څانګو نه به اور بل شى او د لبنان د دِيار ونې به وسوزوى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6301, 'Judges 9:16', 'Judges', 9, 16, '&nbsp;نو يوتام خپله خبره جارى وساتله چې، ”کله تاسو ابى‌مَلِک بادشاه جوړ کړو نو تاسو په رښتيا مخلِصه او رښتونى وئ څۀ؟ تاسو د جدعون د ياد څۀ درناوى وکړو او د هغۀ د خاندان سره مو ښۀ سلوک وکړو څۀ لکه څنګه چې د هغۀ د کارونو حق جوړيږى؟', NULL, '&nbsp;نو يوتام خپله خبره جارى وساتله چې، ”کله تاسو ابى‌مَلِک بادشاه جوړ کړو نو تاسو په رښتيا مخلِصه او رښتونى وئ څۀ؟ تاسو د جدعون د ياد څۀ درناوى وکړو او د هغۀ د خاندان سره مو ښۀ سلوک وکړو څۀ لکه څنګه چې د هغۀ د کارونو حق جوړيږى؟', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6302, 'Judges 9:17', 'Judges', 9, 17, '&nbsp;هغه راپه ياد کړئ چې زما پلار ستاسو دپاره جنګ وکړو. هغۀ خپل ژوند په خطره کښې واچولو چې تاسو د ميديانيانو نه بچ کړى.', NULL, '&nbsp;هغه راپه ياد کړئ چې زما پلار ستاسو دپاره جنګ وکړو. هغۀ خپل ژوند په خطره کښې واچولو چې تاسو د ميديانيانو نه بچ کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6303, 'Judges 9:18', 'Judges', 9, 18, '&nbsp;خو نن تاسو زما د پلار د خاندان خِلاف شوئ. تاسو د هغۀ زامن اويا سړى د يو کاڼى دپاسه ووژل او دا ځکه چې د هغۀ د وينځې زوئ ابى‌مَلِک ستاسو رشته‌دار دے او تاسو هغه د شِکم بادشاه جوړ کړے دے.', NULL, '&nbsp;خو نن تاسو زما د پلار د خاندان خِلاف شوئ. تاسو د هغۀ زامن اويا سړى د يو کاڼى دپاسه ووژل او دا ځکه چې د هغۀ د وينځې زوئ ابى‌مَلِک ستاسو رشته‌دار دے او تاسو هغه د شِکم بادشاه جوړ کړے دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6304, 'Judges 9:19', 'Judges', 9, 19, '&nbsp;کۀ تاسو نن د جدعون او د هغۀ اولاد سره د عزت او ښۀ ايمان سلوک وکړو، نو تاسو دې د ابى‌مَلِک نه خوشحاله شئ او هغه دې ستاسو نه خوشحاله شى.', NULL, '&nbsp;کۀ تاسو نن د جدعون او د هغۀ اولاد سره د عزت او ښۀ ايمان سلوک وکړو، نو تاسو دې د ابى‌مَلِک نه خوشحاله شئ او هغه دې ستاسو نه خوشحاله شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6305, 'Judges 9:20', 'Judges', 9, 20, '&nbsp;خو کۀ داسې نۀ وى نو ابى‌مَلِک ته دې اور بل شى او د شِکم او بيت‌مِلو خلق دې وسوزوى. د شِکم او بيت‌مِلو د خلقو نه دې اور بل شى او ابى‌مَلِک دې وسوزوى.“', NULL, '&nbsp;خو کۀ داسې نۀ وى نو ابى‌مَلِک ته دې اور بل شى او د شِکم او بيت‌مِلو خلق دې وسوزوى. د شِکم او بيت‌مِلو د خلقو نه دې اور بل شى او ابى‌مَلِک دې وسوزوى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6306, 'Judges 9:21', 'Judges', 9, 21, '&nbsp;يوتام د خپل ورور ابى‌مَلِک نه يرېدو نو ځکه هغه وتښتېدو او بير ته د اوسېدو دپاره لاړو.', NULL, '&nbsp;يوتام د خپل ورور ابى‌مَلِک نه يرېدو نو ځکه هغه وتښتېدو او بير ته د اوسېدو دپاره لاړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
