(6309, 'Judges 9:24', 'Judges', 9, 24, '&nbsp;داسې د دې دپاره وشول چې ابى‌مَلِک او د شِکم خلقو ته د خپلو بدو سزا مِلاو شى چا چې د هغۀ مدد کړے وو چې د جدعون اويا زامن ووژنى.', NULL, '&nbsp;داسې د دې دپاره وشول چې ابى‌مَلِک او د شِکم خلقو ته د خپلو بدو سزا مِلاو شى چا چې د هغۀ مدد کړے وو چې د جدعون اويا زامن ووژنى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6310, 'Judges 9:25', 'Judges', 9, 25, '&nbsp;د شِکم خلقو د ابى‌مَلِک خِلاف د غرونو په سرونو باندې په پټ ځائ کښې سړى کښېنول او هر څوک هم چې په هغه لاره تېرېدل نو هغوئ به يې لوټ کول. نو ابى‌مَلِک د دې نه خبر شو.', NULL, '&nbsp;د شِکم خلقو د ابى‌مَلِک خِلاف د غرونو په سرونو باندې په پټ ځائ کښې سړى کښېنول او هر څوک هم چې په هغه لاره تېرېدل نو هغوئ به يې لوټ کول. نو ابى‌مَلِک د دې نه خبر شو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
