(6328, 'Judges 9:43', 'Judges', 9, 43, '&nbsp;نو هغۀ خپل سړى بوتلل، په درېو ډلو کښې يې تقسيم کړل، په پټو کښې پټ شول او اِنتظار يې کولو. کله چې هغۀ وليدل چې خلق د ښار نه بهر روان دى، نو هغه د پټ ځائ نه د هغوئ د وژلو دپاره راووتلو.', NULL, '&nbsp;نو هغۀ خپل سړى بوتلل، په درېو ډلو کښې يې تقسيم کړل، په پټو کښې پټ شول او اِنتظار يې کولو. کله چې هغۀ وليدل چې خلق د ښار نه بهر روان دى، نو هغه د پټ ځائ نه د هغوئ د وژلو دپاره راووتلو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6329, 'Judges 9:44', 'Judges', 9, 44, '&nbsp;کله چې ابى‌مَلِک او د هغۀ قبيله په تېزۍ سره د ښار د دروازې د حِفاظت دپاره مخکښې شوه، نو هغه دوو نورو ډلو په پټو کښې په خلقو باندې حمله وکړه او ټول يې ووژل.', NULL, '&nbsp;کله چې ابى‌مَلِک او د هغۀ قبيله په تېزۍ سره د ښار د دروازې د حِفاظت دپاره مخکښې شوه، نو هغه دوو نورو ډلو په پټو کښې په خلقو باندې حمله وکړه او ټول يې ووژل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6330, 'Judges 9:45', 'Judges', 9, 45, '&nbsp;ټوله ورځ جنګ جارى وو. ابى‌مَلِک ښار قبضه کړو، د هغې خلق يې ووژل، ښار يې وران کړو او زمکه يې په مالګه پټه کړه.', NULL, '&nbsp;ټوله ورځ جنګ جارى وو. ابى‌مَلِک ښار قبضه کړو، د هغې خلق يې ووژل، ښار يې وران کړو او زمکه يې په مالګه پټه کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
