(6377, 'Judges 11:17', 'Judges', 11, 17, '&nbsp;بيا هغوئ د ادوم بادشاه له پېغام وړُونکى ولېږل چې اجازت ترې نه وغواړى چې د هغۀ په مُلک کښې تېر شى. خو د ادوم بادشاه هغوئ نۀ پرېښودل. هغوئ د موآب بادشاه ته هم ووئيل، خو هغۀ هم پرې نۀ ښودل چې د هغۀ په مُلک کښې تېر شى. نو بنى اِسرائيليان په قادِس کښې ايسار شول.', NULL, '&nbsp;بيا هغوئ د ادوم بادشاه له پېغام وړُونکى ولېږل چې اجازت ترې نه وغواړى چې د هغۀ په مُلک کښې تېر شى. خو د ادوم بادشاه هغوئ نۀ پرېښودل. هغوئ د موآب بادشاه ته هم ووئيل، خو هغۀ هم پرې نۀ ښودل چې د هغۀ په مُلک کښې تېر شى. نو بنى اِسرائيليان په قادِس کښې ايسار شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6378, 'Judges 11:18', 'Judges', 11, 18, '&nbsp;بيا هغوئ په صحرا کښې روان وُو، د ادوم او د موآب مُلک نه تاوېدل تر دې پورې چې د موآب نمرخاتۀ طرف ته راغلل چې د ارنون سيند بل طرف ته وو. هغوئ هلته خېمې ولګولې، خو هغوئ د ارنون نه پورې نۀ وتل ځکه چې دا د موآب د حد پوله وه.', NULL, '&nbsp;بيا هغوئ په صحرا کښې روان وُو، د ادوم او د موآب مُلک نه تاوېدل تر دې پورې چې د موآب نمرخاتۀ طرف ته راغلل چې د ارنون سيند بل طرف ته وو. هغوئ هلته خېمې ولګولې، خو هغوئ د ارنون نه پورې نۀ وتل ځکه چې دا د موآب د حد پوله وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
