(6406, 'Judges 12:6', 'Judges', 12, 6, '&nbsp;هغوئ به ورته ووئيل چې، ”شبوليت ووايه.“ خو هغۀ به ورته په جواب کښې ”سبوليت“ ووئيل ځکه چې هغۀ به دا ټکے صحيح نۀ شو وئيلے. نو هغه به يې ونيولو او د اُردن سيند نه د پورې وتو په ځائ کښې به يې ووژلو. په هغه وخت کښې دوه څلوېښت زره اِفرائيميان ووژلے شول.', NULL, '&nbsp;هغوئ به ورته ووئيل چې، ”شبوليت ووايه.“ خو هغۀ به ورته په جواب کښې ”سبوليت“ ووئيل ځکه چې هغۀ به دا ټکے صحيح نۀ شو وئيلے. نو هغه به يې ونيولو او د اُردن سيند نه د پورې وتو په ځائ کښې به يې ووژلو. په هغه وخت کښې دوه څلوېښت زره اِفرائيميان ووژلے شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
