(6421, 'Judges 13:6', 'Judges', 13, 6, '&nbsp;بيا هغه ښځه لاړه او خپل خاوند ته يې ووئيل، ”د خُدائ پاک يو سړے ما له راغلو، هغه د خُدائ پاک د فرښتې په شان هيبتناک ښکارېدو. ما د هغۀ نه تپوس ونۀ وکړو چې د کوم ځائ نه راغلے يې، نو هغۀ ما ته خپل نوم هم ونۀ ښودلو.', NULL, '&nbsp;بيا هغه ښځه لاړه او خپل خاوند ته يې ووئيل، ”د خُدائ پاک يو سړے ما له راغلو، هغه د خُدائ پاک د فرښتې په شان هيبتناک ښکارېدو. ما د هغۀ نه تپوس ونۀ وکړو چې د کوم ځائ نه راغلے يې، نو هغۀ ما ته خپل نوم هم ونۀ ښودلو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6422, 'Judges 13:7', 'Judges', 13, 7, '&nbsp;خو هغۀ ما ته وفرمائيل چې زۀ به اُميدواره شم او يو زوئ به مې وشى. هغۀ راته وفرمائيل چې مے يا شراب مۀ څښه او نۀ چې حرام څيز وخورې، ځکه چې تر کومې پورې هغه ماشوم ژوندے وى نو هغه به خُدائ پاک ته د نذير په حيثيت وقف وى.“', NULL, '&nbsp;خو هغۀ ما ته وفرمائيل چې زۀ به اُميدواره شم او يو زوئ به مې وشى. هغۀ راته وفرمائيل چې مے يا شراب مۀ څښه او نۀ چې حرام څيز وخورې، ځکه چې تر کومې پورې هغه ماشوم ژوندے وى نو هغه به خُدائ پاک ته د نذير په حيثيت وقف وى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
