(6450, 'Judges 14:16', 'Judges', 14, 16, '&nbsp;نو د سمسون ښځه په ژړا هغۀ له ورغله او ورته يې ووئيل، ”تۀ زما سره مينه نۀ کوې. تۀ زما نه کرکه کوې. تا زما د خلقو نه د سخت سوال تپوس وکړو او ما ته دې ونۀ وئيل چې د دې مطلب څۀ دے.“ هغۀ ورته وفرمائيل، ”ګوره، ما خپل مور پلار ته هم نۀ دى وئيلى. نو زۀ تا ته ولې ووايم؟“', NULL, '&nbsp;نو د سمسون ښځه په ژړا هغۀ له ورغله او ورته يې ووئيل، ”تۀ زما سره مينه نۀ کوې. تۀ زما نه کرکه کوې. تا زما د خلقو نه د سخت سوال تپوس وکړو او ما ته دې ونۀ وئيل چې د دې مطلب څۀ دے.“ هغۀ ورته وفرمائيل، ”ګوره، ما خپل مور پلار ته هم نۀ دى وئيلى. نو زۀ تا ته ولې ووايم؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
