(6464, 'Judges 15:10', 'Judges', 15, 10, '&nbsp;د يهوداه سړو د هغوئ نه تپوس وکړو، ”تاسو په مونږ باندې ولې حمله کوئ؟“ هغوئ په جواب کښې ورته ووئيل، ”مونږ د دې دپاره راغلى يُو چې سمسون قېدى بوځُو او هم هغه شان ورسره وکړُو چې څۀ يې زمونږ سره کړى وُو.“', NULL, '&nbsp;د يهوداه سړو د هغوئ نه تپوس وکړو، ”تاسو په مونږ باندې ولې حمله کوئ؟“ هغوئ په جواب کښې ورته ووئيل، ”مونږ د دې دپاره راغلى يُو چې سمسون قېدى بوځُو او هم هغه شان ورسره وکړُو چې څۀ يې زمونږ سره کړى وُو.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
