(6476, 'Judges 16:2', 'Judges', 16, 2, '&nbsp;د غزه خلقو ته پته ولګېده چې سمسون هلته دے، نو هغوئ هغه ځائ نه ګېره واچوله او د ښار په دروازه کښې يې ټوله شپه د هغۀ اِنتظار وکړو. ټوله شپه هغوئ غلى وُو، د خپلو ځانونو سره يې دا سوچ کولو چې، ”د سحر رڼا پورې به مونږ اِنتظار وکړُو او بيا به هغه ووژنو.“', NULL, '&nbsp;د غزه خلقو ته پته ولګېده چې سمسون هلته دے، نو هغوئ هغه ځائ نه ګېره واچوله او د ښار په دروازه کښې يې ټوله شپه د هغۀ اِنتظار وکړو. ټوله شپه هغوئ غلى وُو، د خپلو ځانونو سره يې دا سوچ کولو چې، ”د سحر رڼا پورې به مونږ اِنتظار وکړُو او بيا به هغه ووژنو.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6477, 'Judges 16:3', 'Judges', 16, 3, '&nbsp;خو سمسون تر نيمې شپې پورې د کنجرې سره پروت وو. بيا هغه پاڅېدو او د ښار دروازه يې ونيوله او د تمبو، دُرشلو، تالو او هر څۀ سره يې وويستله. هغۀ دا په خپلو اوږو باندې کېښودل او د هغه غر سر پورې يې يوړل چرته نه چې حبرون ښکارېدو.', NULL, '&nbsp;خو سمسون تر نيمې شپې پورې د کنجرې سره پروت وو. بيا هغه پاڅېدو او د ښار دروازه يې ونيوله او د تمبو، دُرشلو، تالو او هر څۀ سره يې وويستله. هغۀ دا په خپلو اوږو باندې کېښودل او د هغه غر سر پورې يې يوړل چرته نه چې حبرون ښکارېدو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
