(6479, 'Judges 16:5', 'Judges', 16, 5, '&nbsp;هغه پينځۀ فلستى بادشاهان هغې له لاړل او ورته يې ووئيل، ”سمسون وغولوه چې تا ته ووائى چې هغه دومره تکړه ولې دے او مونږ په هغۀ باندې څنګه غالِب راتلے شُو، چې وې تړُو او کمزورے يې کړُو. مونږ هر يو به تا له يوولس سوه د سپينو زرو سيکې درکړُو.“', NULL, '&nbsp;هغه پينځۀ فلستى بادشاهان هغې له لاړل او ورته يې ووئيل، ”سمسون وغولوه چې تا ته ووائى چې هغه دومره تکړه ولې دے او مونږ په هغۀ باندې څنګه غالِب راتلے شُو، چې وې تړُو او کمزورے يې کړُو. مونږ هر يو به تا له يوولس سوه د سپينو زرو سيکې درکړُو.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
