(6487, 'Judges 16:13', 'Judges', 16, 13, '&nbsp;دليلې سمسون ته ووئيل، ”تا تر اوسه پورې زما نه کم عقله جوړه کړې ده او ما ته دروغ وائې. ما ته ووايه چې تۀ څنګه ښۀ تړلے کېدے شې.“ هغۀ ورته وفرمائيل، ”کۀ تۀ زما د وېښتو اووۀ کونسۍ د جامو په خپله کډۍ کښې وګنډې او د کډۍ په سيخ پورې يې وتړې، نو زۀ به د نورو په شان کمزورے يم.“', NULL, '&nbsp;دليلې سمسون ته ووئيل، ”تا تر اوسه پورې زما نه کم عقله جوړه کړې ده او ما ته دروغ وائې. ما ته ووايه چې تۀ څنګه ښۀ تړلے کېدے شې.“ هغۀ ورته وفرمائيل، ”کۀ تۀ زما د وېښتو اووۀ کونسۍ د جامو په خپله کډۍ کښې وګنډې او د کډۍ په سيخ پورې يې وتړې، نو زۀ به د نورو په شان کمزورے يم.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6488, 'Judges 16:14', 'Judges', 16, 14, '&nbsp;دليلې هغه په آرام سره اودۀ کړو، د هغۀ د وېښتو اووۀ کونسۍ يې وګنډلې او د کډۍ په سيخ پورې يې وتړلې او چغه يې کړه، ”سمسونه، ستا د نيولو دپاره فلستيان راغلى دى.“ خو هغه پاڅېدو او خپل وېښتۀ يې د هغه کډۍ نه خلاص کړل.', NULL, '&nbsp;دليلې هغه په آرام سره اودۀ کړو، د هغۀ د وېښتو اووۀ کونسۍ يې وګنډلې او د کډۍ په سيخ پورې يې وتړلې او چغه يې کړه، ”سمسونه، ستا د نيولو دپاره فلستيان راغلى دى.“ خو هغه پاڅېدو او خپل وېښتۀ يې د هغه کډۍ نه خلاص کړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6489, 'Judges 16:15', 'Judges', 16, 15, '&nbsp;نو هغې ورته ووئيل، ”تۀ څنګه وائې چې زما سره مينه کوې، کله چې تۀ په ما اعتبار هم نۀ کوې؟ تا درې ځل زما نه کم عقله جوړه کړه او تا بيا هم ما ته ونۀ وئيل چې تۀ په څۀ باندې دومره تکړه يې.“', NULL, '&nbsp;نو هغې ورته ووئيل، ”تۀ څنګه وائې چې زما سره مينه کوې، کله چې تۀ په ما اعتبار هم نۀ کوې؟ تا درې ځل زما نه کم عقله جوړه کړه او تا بيا هم ما ته ونۀ وئيل چې تۀ په څۀ باندې دومره تکړه يې.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
