(6491, 'Judges 16:17', 'Judges', 16, 17, '&nbsp;نو سمسون آخر کښې هغې ته رښتيا وئيل، ”زما وېښتۀ هيڅکله هم نۀ دى کل شوى. زما د پېدا کېدو د وخت نه زۀ خُدائ پاک ته د نذير په حيثيت وقف يم. کۀ زما وېښتۀ کل شوى وے، نو زما طاقت به ختم شوے وو او د نورو په شان به کمزورے وم.“', NULL, '&nbsp;نو سمسون آخر کښې هغې ته رښتيا وئيل، ”زما وېښتۀ هيڅکله هم نۀ دى کل شوى. زما د پېدا کېدو د وخت نه زۀ خُدائ پاک ته د نذير په حيثيت وقف يم. کۀ زما وېښتۀ کل شوى وے، نو زما طاقت به ختم شوے وو او د نورو په شان به کمزورے وم.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6492, 'Judges 16:18', 'Judges', 16, 18, '&nbsp;کله چې دليلې ته پته ولګېده چې هغۀ ورته ټول راز وښودلو، نو هغې فلستى بادشاهانو ته يو پېغام ولېږلو او ورته يې ووئيل، ”تاسو يو ځل بيا راشئ. سمسون ما ته رښتيا وئيلى دى.“ نو هغوئ راغلل او د ځان سره يې پېسې هم راوړې.', NULL, '&nbsp;کله چې دليلې ته پته ولګېده چې هغۀ ورته ټول راز وښودلو، نو هغې فلستى بادشاهانو ته يو پېغام ولېږلو او ورته يې ووئيل، ”تاسو يو ځل بيا راشئ. سمسون ما ته رښتيا وئيلى دى.“ نو هغوئ راغلل او د ځان سره يې پېسې هم راوړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
