(6506, 'Judges 17:3', 'Judges', 17, 3, '&nbsp;هغۀ پېسې واپس خپلې مور له ورکړې او مور يې ووئيل، ”چې هغه ښېرې زما په زوئ باندې ونۀ لګى زۀ پخپله دا د سپينو زرو سيکې مالِک خُدائ ته وقف کوم. د لرګى په يوه مجسمه به دا سپين زر وخېژولے شى. نو داسې به زۀ دا د سپينو زرو سيکې تا له واپس درکړم.“', NULL, '&nbsp;هغۀ پېسې واپس خپلې مور له ورکړې او مور يې ووئيل، ”چې هغه ښېرې زما په زوئ باندې ونۀ لګى زۀ پخپله دا د سپينو زرو سيکې مالِک خُدائ ته وقف کوم. د لرګى په يوه مجسمه به دا سپين زر وخېژولے شى. نو داسې به زۀ دا د سپينو زرو سيکې تا له واپس درکړم.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6507, 'Judges 17:4', 'Judges', 17, 4, '&nbsp;کله يې چې دا واپس خپلې مور له ورکړې نو هغې دوه سوه د سپينو زرو سيکې يوړې او زرګر د لرګى بُت جوړ کړو او سپين زر يې پرې وخېژول. دا د ميکاه په کور کښې کېښودے شول.', NULL, '&nbsp;کله يې چې دا واپس خپلې مور له ورکړې نو هغې دوه سوه د سپينو زرو سيکې يوړې او زرګر د لرګى بُت جوړ کړو او سپين زر يې پرې وخېژول. دا د ميکاه په کور کښې کېښودے شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6508, 'Judges 17:5', 'Judges', 17, 5, '&nbsp;د دې سړى يعنې د ميکاه يوه بُت‌خانه وه. هغۀ څۀ بُتان او يو مقدس پېش بند جوړ کړو. او خپل يو زوئ يې خپل اِمام مقرر کړو.', NULL, '&nbsp;د دې سړى يعنې د ميکاه يوه بُت‌خانه وه. هغۀ څۀ بُتان او يو مقدس پېش بند جوړ کړو. او خپل يو زوئ يې خپل اِمام مقرر کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
