(6530, 'Judges 18:14', 'Judges', 18, 14, '&nbsp;بيا هغه پينځۀ سړى کوم چې د ليس مُلک کتلو له تلى وُو هغوئ خپلو ملګرو ته ووئيل، ”تاسو ته پته وه څۀ چې هلته په يو کور کښې يوه مجسمه او يو په قالب کښې جوړ شوے بُت دے؟ هلته نور بُتان او مقدس پېش بند هم دى. ستاسو څۀ خيال دے چې څۀ وکړُو؟“', NULL, '&nbsp;بيا هغه پينځۀ سړى کوم چې د ليس مُلک کتلو له تلى وُو هغوئ خپلو ملګرو ته ووئيل، ”تاسو ته پته وه څۀ چې هلته په يو کور کښې يوه مجسمه او يو په قالب کښې جوړ شوے بُت دے؟ هلته نور بُتان او مقدس پېش بند هم دى. ستاسو څۀ خيال دے چې څۀ وکړُو؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
