(6532, 'Judges 18:16', 'Judges', 18, 16, '&nbsp;په دې دوران کښې چې د دان کوم شپږ سوه فوجيان چې د جنګ دپاره تيار وُو، هغوئ په دروازه کښې ولاړ وُو.', NULL, '&nbsp;په دې دوران کښې چې د دان کوم شپږ سوه فوجيان چې د جنګ دپاره تيار وُو، هغوئ په دروازه کښې ولاړ وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
