(6534, 'Judges 18:18', 'Judges', 18, 18, '&nbsp;کله چې سړى د ميکاه کور ته ننوتل او مقدس څيزونه يې راواخستل، نو اِمام د هغوئ نه تپوس وکړو، ”تاسو څۀ کوئ؟“', NULL, '&nbsp;کله چې سړى د ميکاه کور ته ننوتل او مقدس څيزونه يې راواخستل، نو اِمام د هغوئ نه تپوس وکړو، ”تاسو څۀ کوئ؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6535, 'Judges 18:19', 'Judges', 18, 19, '&nbsp;هغوئ ورته ووئيل، ”غلے شه. چې يوه خبره هم ونۀ کړې. مونږ سره لاړ شه او زمونږ اِمام او مشر شه. د يو سړى د خاندان د اِمام کېدو نه دا ښه نۀ ده څۀ چې د بنى اِسرائيلو د يوې قبيلې اِمام شې؟“', NULL, '&nbsp;هغوئ ورته ووئيل، ”غلے شه. چې يوه خبره هم ونۀ کړې. مونږ سره لاړ شه او زمونږ اِمام او مشر شه. د يو سړى د خاندان د اِمام کېدو نه دا ښه نۀ ده څۀ چې د بنى اِسرائيلو د يوې قبيلې اِمام شې؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6536, 'Judges 18:20', 'Judges', 18, 20, '&nbsp;نو اِمام په دې باندې ډېر خوشحاله شو او هغه مقدس څيزونه يې واخستل او د هغوئ سره لاړو.', NULL, '&nbsp;نو اِمام په دې باندې ډېر خوشحاله شو او هغه مقدس څيزونه يې واخستل او د هغوئ سره لاړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
