(6548, 'Judges 19:3', 'Judges', 19, 3, '&nbsp;بيا هغه سړى دا فېصله وکړه چې هغې پسې لاړ شى او رضا يې کړى چې واپس هغۀ له راشى. هغۀ خپل نوکر او دوه خرونه ځان سره بوتلل. نو کله چې هغه هلته ورسېدو نو ښځې هغه د خپل پلار کور ته راوستو او چې سخر هغه وليدو نو ورته يې ډېر په مينه پخېر راغلے ووئيلو.', NULL, '&nbsp;بيا هغه سړى دا فېصله وکړه چې هغې پسې لاړ شى او رضا يې کړى چې واپس هغۀ له راشى. هغۀ خپل نوکر او دوه خرونه ځان سره بوتلل. نو کله چې هغه هلته ورسېدو نو ښځې هغه د خپل پلار کور ته راوستو او چې سخر هغه وليدو نو ورته يې ډېر په مينه پخېر راغلے ووئيلو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6549, 'Judges 19:4', 'Judges', 19, 4, '&nbsp;د هغۀ سخر پرې زور واچولو چې ايسار شى، نو هغه درې ورځې هلته پاتې شو. هغوئ هلته خوراک څښاک وکړو او درې شپې يې تېرې کړې.', NULL, '&nbsp;د هغۀ سخر پرې زور واچولو چې ايسار شى، نو هغه درې ورځې هلته پاتې شو. هغوئ هلته خوراک څښاک وکړو او درې شپې يې تېرې کړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6550, 'Judges 19:5', 'Judges', 19, 5, '&nbsp;د څلورمې ورځې په سحر هغوئ وختى پاڅېدل او د تلو تيارے يې وکړو. خو د ښځې پلار هغه ليوى ته ووئيل، ”وړومبے لږ څۀ وخوره. چې تازه دم شې نو وروستو به بيا لاړ شې.“', NULL, '&nbsp;د څلورمې ورځې په سحر هغوئ وختى پاڅېدل او د تلو تيارے يې وکړو. خو د ښځې پلار هغه ليوى ته ووئيل، ”وړومبے لږ څۀ وخوره. چې تازه دم شې نو وروستو به بيا لاړ شې.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6551, 'Judges 19:6', 'Judges', 19, 6, '&nbsp;نو هغه دواړه سړى کښېناستل او په يو ځائ يې خوراک څښاک وکړو. د ښځې پلار بيا هغۀ ته ووئيل، ”دا به ښۀ وى چې شپه دلته تېره کړې او خپل زړۀ خوشحاله کړې.“', NULL, '&nbsp;نو هغه دواړه سړى کښېناستل او په يو ځائ يې خوراک څښاک وکړو. د ښځې پلار بيا هغۀ ته ووئيل، ”دا به ښۀ وى چې شپه دلته تېره کړې او خپل زړۀ خوشحاله کړې.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6552, 'Judges 19:7', 'Judges', 19, 7, '&nbsp;ليوے پاڅېدو چې لاړ شى، خو د هغۀ سخر ورته مِنت وکړو چې ايسار شى، نو هغۀ يوه بله شپه هم هلته تېره کړه.', NULL, '&nbsp;ليوے پاڅېدو چې لاړ شى، خو د هغۀ سخر ورته مِنت وکړو چې ايسار شى، نو هغۀ يوه بله شپه هم هلته تېره کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6553, 'Judges 19:8', 'Judges', 19, 8, '&nbsp;په پينځمه ورځ سحر وختى هغه روان شو، خو سخر ورته ووئيل، ”لږ څۀ وخوره او مازيګر پورې صبر وکړه.“ نو دواړو سړو يو ځائ روټۍ وخوړه.', NULL, '&nbsp;په پينځمه ورځ سحر وختى هغه روان شو، خو سخر ورته ووئيل، ”لږ څۀ وخوره او مازيګر پورې صبر وکړه.“ نو دواړو سړو يو ځائ روټۍ وخوړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6554, 'Judges 19:9', 'Judges', 19, 9, '&nbsp;کله چې هغه سړے، د هغۀ وينځه او د هغۀ نوکر يو ځل بيا روان شول، نو سخر ورته ووئيل، ”وګوره، ماښام نزدې دے، په کار دى چې تاسو ټوله شپه پاتې شئ. زر به تيارۀ شى، دلته پاتې شئ او خپل زړۀ خوشحاله کړئ. سحر د سفر دپاره وختى پاڅئ او خپل کور ته لاړ شئ.“', NULL, '&nbsp;کله چې هغه سړے، د هغۀ وينځه او د هغۀ نوکر يو ځل بيا روان شول، نو سخر ورته ووئيل، ”وګوره، ماښام نزدې دے، په کار دى چې تاسو ټوله شپه پاتې شئ. زر به تيارۀ شى، دلته پاتې شئ او خپل زړۀ خوشحاله کړئ. سحر د سفر دپاره وختى پاڅئ او خپل کور ته لاړ شئ.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6555, 'Judges 19:14', 'Judges', 19, 14, '&nbsp;نو هغوئ د يبوس نه تېر شول او په خپله مخه روان وُو. نمر په پرېوتو وو چې هغوئ د بنيامين په علاقه کښې جبعې ته راغلل.', NULL, '&nbsp;نو هغوئ د يبوس نه تېر شول او په خپله مخه روان وُو. نمر په پرېوتو وو چې هغوئ د بنيامين په علاقه کښې جبعې ته راغلل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6556, 'Judges 19:15', 'Judges', 19, 15, '&nbsp;هغوئ د شپې تېرولو دپاره ورغلل. هغوئ ښار ته لاړل او په بازار کښې کښېناستل، خو هيچا د شپې دپاره کور ته بونۀ تلل.', NULL, '&nbsp;هغوئ د شپې تېرولو دپاره ورغلل. هغوئ ښار ته لاړل او په بازار کښې کښېناستل، خو هيچا د شپې دپاره کور ته بونۀ تلل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6557, 'Judges 19:16', 'Judges', 19, 16, '&nbsp;څۀ وخت چې هغوئ هلته وُو، نو يو بوډا سړے راغلو چې ټوله ورځ يې په پټو کښې کار کړے وو. په اصل کښې هغه د اِفرائيم د غرونو د مُلک وو، خو اوس په جبعه کښې اوسېدو. (هلته نور خلق د بنيامين د قبيلې وُو.)', NULL, '&nbsp;څۀ وخت چې هغوئ هلته وُو، نو يو بوډا سړے راغلو چې ټوله ورځ يې په پټو کښې کار کړے وو. په اصل کښې هغه د اِفرائيم د غرونو د مُلک وو، خو اوس په جبعه کښې اوسېدو. (هلته نور خلق د بنيامين د قبيلې وُو.)', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6558, 'Judges 19:17', 'Judges', 19, 17, '&nbsp;هغه بوډا سړى د ښار په بازار کښې مسافر وليدو او تپوس يې ترې نه وکړو، ”تۀ د کوم ځائ نه راغلے يې؟ او تۀ چرته ځې؟“', NULL, '&nbsp;هغه بوډا سړى د ښار په بازار کښې مسافر وليدو او تپوس يې ترې نه وکړو، ”تۀ د کوم ځائ نه راغلے يې؟ او تۀ چرته ځې؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6559, 'Judges 19:18', 'Judges', 19, 18, '&nbsp;ليوى جواب ورکړو، ”مونږ د يهوداه په بيت‌لحم کښې وُو او اوس مونږ د اِفرائيم د غرونو مُلک لرې برخې ته روان يُو د کوم نه چې زۀ راغلے يم. خو داسې هيڅ څوک هم نشته چې مونږ خپل کور ته بوځى،', NULL, '&nbsp;ليوى جواب ورکړو، ”مونږ د يهوداه په بيت‌لحم کښې وُو او اوس مونږ د اِفرائيم د غرونو مُلک لرې برخې ته روان يُو د کوم نه چې زۀ راغلے يم. خو داسې هيڅ څوک هم نشته چې مونږ خپل کور ته بوځى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6560, 'Judges 19:19', 'Judges', 19, 19, '&nbsp;زمونږ سره د خپلو خرونو دپاره واښۀ او بوس هم شته او داسې زما، زما د بلې ښځې او زما د نوکر دپاره روټۍ او مے هم شته. ما سره د ضرورت هر يو څيز موجود دے.“', NULL, '&nbsp;زمونږ سره د خپلو خرونو دپاره واښۀ او بوس هم شته او داسې زما، زما د بلې ښځې او زما د نوکر دپاره روټۍ او مے هم شته. ما سره د ضرورت هر يو څيز موجود دے.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6561, 'Judges 19:20', 'Judges', 19, 20, '&nbsp;هغه بوډا سړى ورته ووئيل، ”په خېر راغلئ. زۀ به ستاسو د هر ضرورت خيال ساتم، تاسو په بازار کښې شپه مۀ تېروئ.“', NULL, '&nbsp;هغه بوډا سړى ورته ووئيل، ”په خېر راغلئ. زۀ به ستاسو د هر ضرورت خيال ساتم، تاسو په بازار کښې شپه مۀ تېروئ.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
