(6566, 'Judges 19:25', 'Judges', 19, 25, '&nbsp;خو هغه سړو د هغۀ خبره نۀ منله. نو ليوى خپله وينځه بهر ورولېږله. نو هغوئ ورسره په زور زنا وکړه او ټوله شپه يې د هغې بې‌عزتى وکړه او په سحر کښې يې پرېښودله.', NULL, '&nbsp;خو هغه سړو د هغۀ خبره نۀ منله. نو ليوى خپله وينځه بهر ورولېږله. نو هغوئ ورسره په زور زنا وکړه او ټوله شپه يې د هغې بې‌عزتى وکړه او په سحر کښې يې پرېښودله.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6567, 'Judges 19:26', 'Judges', 19, 26, '&nbsp;د سحر په رڼا کښې هغه ښځه راغله او د هغه بوډا سړى د کور په دروازه کښې وغورزېدله، چرته يې چې خاوند وو. د نمر راختلو پورې هغه هلته وه.', NULL, '&nbsp;د سحر په رڼا کښې هغه ښځه راغله او د هغه بوډا سړى د کور په دروازه کښې وغورزېدله، چرته يې چې خاوند وو. د نمر راختلو پورې هغه هلته وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6568, 'Judges 19:27', 'Judges', 19, 27, '&nbsp;سحر د هغې خاوند پاڅېدو او کله چې هغۀ دروازه کولاو کړه چې په خپله مخه لاړ شى، نو هغۀ د کور په مخکښې خپله وينځه وليده چې د دروازې په خولۀ کښې پرَته وه او لاسونه يې درشل ته رسېدلى وُو.', NULL, '&nbsp;سحر د هغې خاوند پاڅېدو او کله چې هغۀ دروازه کولاو کړه چې په خپله مخه لاړ شى، نو هغۀ د کور په مخکښې خپله وينځه وليده چې د دروازې په خولۀ کښې پرَته وه او لاسونه يې درشل ته رسېدلى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
