(6613, 'Judges 20:48', 'Judges', 20, 48, '&nbsp;بنى اِسرائيليان هغه پاتې شوو بنيامينيانو پسې راواپس شول او ټول سړى، ښځې، ماشومان او داسې ځناور يې هم ووژل. هغوئ په هغه علاقه کښې هر يو ښار وسوزولو.', NULL, '&nbsp;بنى اِسرائيليان هغه پاتې شوو بنيامينيانو پسې راواپس شول او ټول سړى، ښځې، ماشومان او داسې ځناور يې هم ووژل. هغوئ په هغه علاقه کښې هر يو ښار وسوزولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6614, 'Judges 21:1', 'Judges', 21, 1, '&nbsp;کله چې بنى اِسرائيليان په مصفاه کښې راغونډ شوى وُو، نو هغوئ د مالِک خُدائ سره دا پوخ لوظ کړے وو چې، ”زمونږ يو کس به هم يو بنيامينى له خپله لور نۀ ورکوى.“', NULL, '&nbsp;کله چې بنى اِسرائيليان په مصفاه کښې راغونډ شوى وُو، نو هغوئ د مالِک خُدائ سره دا پوخ لوظ کړے وو چې، ”زمونږ يو کس به هم يو بنيامينى له خپله لور نۀ ورکوى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6615, 'Judges 21:2', 'Judges', 21, 2, '&nbsp;نو اوس د بنى اِسرائيلو خلق بيت‌ايل ته لاړل او هلته تر ماښامه پورې د خُدائ پاک په حضور کښې ناست وُو. هغوئ په چغو چغو او د ډېر فرياد سره ژړا وکړه،', NULL, '&nbsp;نو اوس د بنى اِسرائيلو خلق بيت‌ايل ته لاړل او هلته تر ماښامه پورې د خُدائ پاک په حضور کښې ناست وُو. هغوئ په چغو چغو او د ډېر فرياد سره ژړا وکړه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
