(6617, 'Judges 21:4', 'Judges', 21, 4, '&nbsp;بل سحر وختى خلقو هلته يو قربان‌ګاه جوړه کړه او د سلامتۍ نذرانې او سوزېدونکې نذرانې يې پېش کړې.', NULL, '&nbsp;بل سحر وختى خلقو هلته يو قربان‌ګاه جوړه کړه او د سلامتۍ نذرانې او سوزېدونکې نذرانې يې پېش کړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
