(6630, 'Judges 21:17', 'Judges', 21, 17, '&nbsp;داسې دې بېخى ونۀ شى چې د بنى اِسرائيلو د دولسو قبيلو نه يوه ختمه شى. مونږ له داسې څۀ طريقه لټول په کار دى چې د بنيامين قبيله ژوندۍ پاتې شى،', NULL, '&nbsp;داسې دې بېخى ونۀ شى چې د بنى اِسرائيلو د دولسو قبيلو نه يوه ختمه شى. مونږ له داسې څۀ طريقه لټول په کار دى چې د بنيامين قبيله ژوندۍ پاتې شى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6631, 'Judges 21:18', 'Judges', 21, 18, '&nbsp;خو مونږ دا اجازت نه شُو ورکولے چې زمونږ لوڼه وادۀ کړى، ځکه چې مونږ په هغه کس باندې لعنت وئيلے دے چې يو بنيامينى له اجازت ورکړى چې زمونږ د لوڼو نه يوه وادۀ کړى.“', NULL, '&nbsp;خو مونږ دا اجازت نه شُو ورکولے چې زمونږ لوڼه وادۀ کړى، ځکه چې مونږ په هغه کس باندې لعنت وئيلے دے چې يو بنيامينى له اجازت ورکړى چې زمونږ د لوڼو نه يوه وادۀ کړى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6632, 'Judges 21:19', 'Judges', 21, 19, '&nbsp;بيا هغوئ ووئيل، ”په سيلا کښې د مالِک خُدائ کلنى مېله زر راروانه ده.“ د بيت‌ايل شمال او د لبونه جنوب طرف ته او د بيت‌ايل او شِکم په مينځ کښې چې کومه لار ده او نمرخاتۀ طرف ته سيلا دے.', NULL, '&nbsp;بيا هغوئ ووئيل، ”په سيلا کښې د مالِک خُدائ کلنى مېله زر راروانه ده.“ د بيت‌ايل شمال او د لبونه جنوب طرف ته او د بيت‌ايل او شِکم په مينځ کښې چې کومه لار ده او نمرخاتۀ طرف ته سيلا دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6633, 'Judges 21:20', 'Judges', 21, 20, '&nbsp;هغوئ بنيامينيانو ته ووئيل، ”لاړ شئ او د انګورو په باغونو کښې پټ شئ', NULL, '&nbsp;هغوئ بنيامينيانو ته ووئيل، ”لاړ شئ او د انګورو په باغونو کښې پټ شئ', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6634, 'Judges 21:21', 'Judges', 21, 21, '&nbsp;او وګورئ، کله چې په مېله کښې د سيلا جينکۍ ګډېدو له راوځى نو تاسو د انګورو باغونو نه راوځئ. نو تاسو هر يو کس يوه يوه ښځه د هغوئ نه په زور راونيسئ او د بنيامين علاقې ته يې د ځان سره بوځئ.', NULL, '&nbsp;او وګورئ، کله چې په مېله کښې د سيلا جينکۍ ګډېدو له راوځى نو تاسو د انګورو باغونو نه راوځئ. نو تاسو هر يو کس يوه يوه ښځه د هغوئ نه په زور راونيسئ او د بنيامين علاقې ته يې د ځان سره بوځئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6635, 'Judges 21:22', 'Judges', 21, 22, '&nbsp;کۀ د هغوئ پلاران يا وروڼه مونږ له راشى او اِعتراض وکړى، نو مونږ به ورته ووايو چې د هغوئ سره ښېګړه وکړئ او هغوئ دې ستاسو لوڼه د ځان دپاره وساتى، ځکه چې مونږ ته په جنګ کښې د ټولو سړو دپاره ښځې نۀ دى مِلاو شوې. او چې تاسو خپلې لوڼه هغوئ له نۀ دى ورکړې نو په دې وجه تاسو ګناهګار نۀ يئ.“', NULL, '&nbsp;کۀ د هغوئ پلاران يا وروڼه مونږ له راشى او اِعتراض وکړى، نو مونږ به ورته ووايو چې د هغوئ سره ښېګړه وکړئ او هغوئ دې ستاسو لوڼه د ځان دپاره وساتى، ځکه چې مونږ ته په جنګ کښې د ټولو سړو دپاره ښځې نۀ دى مِلاو شوې. او چې تاسو خپلې لوڼه هغوئ له نۀ دى ورکړې نو په دې وجه تاسو ګناهګار نۀ يئ.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6636, 'Judges 21:23', 'Judges', 21, 23, '&nbsp;بنيامينيانو هم داسې وکړل، د هغوئ هر يو کس د هغه ښځو نه يوه يوه ښځه خوښه کړه کومې چې په سيلا کښې ګډېدې او بو يې تلې. بيا هغوئ واپس خپلې علاقې ته لاړل، خپل ښارونه يې دوباره جوړ کړل او هلته اوسېدل.', NULL, '&nbsp;بنيامينيانو هم داسې وکړل، د هغوئ هر يو کس د هغه ښځو نه يوه يوه ښځه خوښه کړه کومې چې په سيلا کښې ګډېدې او بو يې تلې. بيا هغوئ واپس خپلې علاقې ته لاړل، خپل ښارونه يې دوباره جوړ کړل او هلته اوسېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
