(6649, 'Ruth 1:13', 'Ruth', 1, 13, '&nbsp;تاسو به د هغوئ د غټېدو اِنتظار کوئ څۀ؟ دا به تاسو د بل چا سره د ودېدو نه ايساروى څۀ؟ نه، زما لوڼو، تاسو ته پته ده چې دا نۀ شى کېدے. مالِک خُدائ زما مل نۀ دے، په تاسو زما زړۀ سوزى.“', NULL, '&nbsp;تاسو به د هغوئ د غټېدو اِنتظار کوئ څۀ؟ دا به تاسو د بل چا سره د ودېدو نه ايساروى څۀ؟ نه، زما لوڼو، تاسو ته پته ده چې دا نۀ شى کېدے. مالِک خُدائ زما مل نۀ دے، په تاسو زما زړۀ سوزى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6650, 'Ruth 1:14', 'Ruth', 1, 14, '&nbsp;دوئ بيا په ژړا شوې. عرفه په مخه ښه وئيلو دپاره خواښې ښُکله کړه او واپس کور ته لاړه، خو روت د هغې لمن نيولې وه.', NULL, '&nbsp;دوئ بيا په ژړا شوې. عرفه په مخه ښه وئيلو دپاره خواښې ښُکله کړه او واپس کور ته لاړه، خو روت د هغې لمن نيولې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6651, 'Ruth 1:15', 'Ruth', 1, 15, '&nbsp;نو نعومى هغې ته ووئيل، ”اے روت، ستا يور خپلو خلقو او د هغوئ معبودانو له لاړه. هغې پسې واپس کور ته لاړه شه.“', NULL, '&nbsp;نو نعومى هغې ته ووئيل، ”اے روت، ستا يور خپلو خلقو او د هغوئ معبودانو له لاړه. هغې پسې واپس کور ته لاړه شه.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6652, 'Ruth 1:16', 'Ruth', 1, 16, '&nbsp;خو روت ورته ووئيل، ”ما د ځان نه مۀ شړه، ما ته مۀ وايه چې درنه ايساره شم. چې چرته ځې، هلته به ځم، چې چرته اوسې، هلته به اوسم. ستا خلق به زما خلق وى، او ستاسو خُدائ پاک به زما خُدائ پاک وى.', NULL, '&nbsp;خو روت ورته ووئيل، ”ما د ځان نه مۀ شړه، ما ته مۀ وايه چې درنه ايساره شم. چې چرته ځې، هلته به ځم، چې چرته اوسې، هلته به اوسم. ستا خلق به زما خلق وى، او ستاسو خُدائ پاک به زما خُدائ پاک وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6653, 'Ruth 1:17', 'Ruth', 1, 17, '&nbsp;چې چرته مرې، هلته به مرم، چې چرته ښخېږې هلته به ښخېږم. مالِک خُدائ دې ما ته په قهر شى کۀ د مرګ نه بغېر په بل څۀ ستا نه جدا شم.“', NULL, '&nbsp;چې چرته مرې، هلته به مرم، چې چرته ښخېږې هلته به ښخېږم. مالِک خُدائ دې ما ته په قهر شى کۀ د مرګ نه بغېر په بل څۀ ستا نه جدا شم.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6654, 'Ruth 1:18', 'Ruth', 1, 18, '&nbsp;کله چې نعومى ته پته ولګېده چې روت د تلو کلکه اراده کړې ده، نو هغې نور څۀ ورته ونۀ وئيل.', NULL, '&nbsp;کله چې نعومى ته پته ولګېده چې روت د تلو کلکه اراده کړې ده، نو هغې نور څۀ ورته ونۀ وئيل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
