(6674, 'Ruth 2:18', 'Ruth', 2, 18, '&nbsp;نو هغې دا ښار ته يوړل او خواښې ته يې وښودل چې هغې څومره راټول کړى دى. او د هغې د خوراک نه پاتې شوې وريتى دانې يې هم هغې له ورکړې.', NULL, '&nbsp;نو هغې دا ښار ته يوړل او خواښې ته يې وښودل چې هغې څومره راټول کړى دى. او د هغې د خوراک نه پاتې شوې وريتى دانې يې هم هغې له ورکړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6675, 'Ruth 2:19', 'Ruth', 2, 19, '&nbsp;نعومى د هغې نه تپوس وکړو، ”تا نن دا دومره وَږى چرته نه راټول کړى دى؟ تا د چا په پټى کښې کار کولو؟ هغه سړے دې بختور شى چې ستا خيال يې وساتلو.“ نو روت نعومى ته ووئيل چې، ”نن ما د چا په پټو کښې کار کولو د هغه سړى نوم بوعز دے.“', NULL, '&nbsp;نعومى د هغې نه تپوس وکړو، ”تا نن دا دومره وَږى چرته نه راټول کړى دى؟ تا د چا په پټى کښې کار کولو؟ هغه سړے دې بختور شى چې ستا خيال يې وساتلو.“ نو روت نعومى ته ووئيل چې، ”نن ما د چا په پټو کښې کار کولو د هغه سړى نوم بوعز دے.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
