(6678, 'Ruth 2:22', 'Ruth', 2, 22, '&nbsp;نعومى روت ته ووئيل، ”آو لورې، دا به ډېره ښۀ وى چې د بوعز په پټو کښې د ښځو سره کار کوې. کۀ چرې تۀ د بل چا پټو ته لاړې نو څوک به لاس درواچوى.“', NULL, '&nbsp;نعومى روت ته ووئيل، ”آو لورې، دا به ډېره ښۀ وى چې د بوعز په پټو کښې د ښځو سره کار کوې. کۀ چرې تۀ د بل چا پټو ته لاړې نو څوک به لاس درواچوى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
