(6698, 'Ruth 4:1', 'Ruth', 4, 1, '&nbsp;نو بوعز د ښار په دروازه کښې د جرګې ځائ ته لاړو او هلته کښېناستو. بيا د اِلى‌مَلِک نزدې رشته‌دار، چې بوعز د هغۀ په حقله وئيلى وُو، راغلو، نو بوعز ورته آواز وکړو، ”زما ملګريه، دېخوا راشه، او دلته کښېنه.“ هغه ورَغلو او هلته کښېناستو.', NULL, '&nbsp;نو بوعز د ښار په دروازه کښې د جرګې ځائ ته لاړو او هلته کښېناستو. بيا د اِلى‌مَلِک نزدې رشته‌دار، چې بوعز د هغۀ په حقله وئيلى وُو، راغلو، نو بوعز ورته آواز وکړو، ”زما ملګريه، دېخوا راشه، او دلته کښېنه.“ هغه ورَغلو او هلته کښېناستو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
