(6701, 'Ruth 4:4', 'Ruth', 4, 4, '&nbsp;زما خيال دا دے چې تۀ د دې په حقله خبر شې. نو بيا، کۀ دا اخستل غواړې، نو د دې ناستو کسانو په مخکښې ووايه، او کۀ نۀ غواړې، نو هم ووايه، ځکه چې د دې اخستلو اول حق ستا دے او بيا زما.“ هغه سړى ووئيل، ”زۀ به دا واخلم.“', NULL, '&nbsp;زما خيال دا دے چې تۀ د دې په حقله خبر شې. نو بيا، کۀ دا اخستل غواړې، نو د دې ناستو کسانو په مخکښې ووايه، او کۀ نۀ غواړې، نو هم ووايه، ځکه چې د دې اخستلو اول حق ستا دے او بيا زما.“ هغه سړى ووئيل، ”زۀ به دا واخلم.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6702, 'Ruth 4:5', 'Ruth', 4, 5, '&nbsp;بوعز ووئيل، ”ډېره ښۀ ده، کۀ تۀ د نعومى نه پټے اخلې نو ورسره روت هغه موآبۍ کونډه به هم اخلې، نو دا پټے به د مړى د خاندان په ميراث کښې راځى.“', NULL, '&nbsp;بوعز ووئيل، ”ډېره ښۀ ده، کۀ تۀ د نعومى نه پټے اخلې نو ورسره روت هغه موآبۍ کونډه به هم اخلې، نو دا پټے به د مړى د خاندان په ميراث کښې راځى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6703, 'Ruth 4:6', 'Ruth', 4, 6, '&nbsp;هغۀ جواب ورکړو، ”نو په دې وجه زۀ بيا داسې نۀ شم کولے، زۀ خپل حق پرېږدم، کۀ تۀ يې اخستل غواړې نو وا يې خله. ځکه چې د دې مطلب دا دے چې دا به زما د بچو ميراث نۀ وى. نو هم تۀ يې واخله، زما نۀ دے په کار.“', NULL, '&nbsp;هغۀ جواب ورکړو، ”نو په دې وجه زۀ بيا داسې نۀ شم کولے، زۀ خپل حق پرېږدم، کۀ تۀ يې اخستل غواړې نو وا يې خله. ځکه چې د دې مطلب دا دے چې دا به زما د بچو ميراث نۀ وى. نو هم تۀ يې واخله، زما نۀ دے په کار.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
