(6749, '1 Samuel 2:9', '1 Samuel', 2, 9, '&nbsp;هغه د خپلو وفادارو خلقو ژوند بچ کوى، خو بدعمله په تيارۀ کښې ورکيږى، سړے په خپل طاقت باندې نۀ بريالے کيږى.', NULL, '&nbsp;هغه د خپلو وفادارو خلقو ژوند بچ کوى، خو بدعمله په تيارۀ کښې ورکيږى، سړے په خپل طاقت باندې نۀ بريالے کيږى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6750, '1 Samuel 2:10', '1 Samuel', 2, 10, '&nbsp;د مالِک خُدائ دشمنان به تباه شى، هغه به د هغوئ خِلاف د آسمان د تندر په شان شى. مالِک خُدائ به د ټولې دُنيا عدالت کوى، هغه به خپل بادشاه له طاقت ورکړى، هغه به خپل خوښ کړے شوے بادشاه بريالے کړى.“', NULL, '&nbsp;د مالِک خُدائ دشمنان به تباه شى، هغه به د هغوئ خِلاف د آسمان د تندر په شان شى. مالِک خُدائ به د ټولې دُنيا عدالت کوى، هغه به خپل بادشاه له طاقت ورکړى، هغه به خپل خوښ کړے شوے بادشاه بريالے کړى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6751, '1 Samuel 2:11', '1 Samuel', 2, 11, '&nbsp;بيا القنه واپس په راما کښې کور ته لاړو، خو سموئيل په سيلا کښې پاتې شو او د عيلى اِمام د مشرۍ لاندې يې د مالِک خُدائ خِدمت کولو.', NULL, '&nbsp;بيا القنه واپس په راما کښې کور ته لاړو، خو سموئيل په سيلا کښې پاتې شو او د عيلى اِمام د مشرۍ لاندې يې د مالِک خُدائ خِدمت کولو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
