(6753, '1 Samuel 2:13', '1 Samuel', 2, 13, '&nbsp;او نۀ يې د هغه اصُولو خيال وساتلو چې د اِمامانو د برخې په حقله وُو. او کله به چې چا يوه نذرانه پېش کوله او چې غوښه به لا پخېدله نو د اِمام نوکر به د يو درې غاښى سره راغلو،', NULL, '&nbsp;او نۀ يې د هغه اصُولو خيال وساتلو چې د اِمامانو د برخې په حقله وُو. او کله به چې چا يوه نذرانه پېش کوله او چې غوښه به لا پخېدله نو د اِمام نوکر به د يو درې غاښى سره راغلو،', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6754, '1 Samuel 2:14', '1 Samuel', 2, 14, '&nbsp;هغۀ به درې غاښے د پخلى لوښى ته ورننويستلو او چې درې غاښى به څۀ هم راوويستل نو هغه به د اِمام وُو. د هغه ټولو بنى اِسرائيلو سره هم داسې سلوک وشو چې د قربانۍ پېش کولو دپاره سيلا ښار ته راغلى وُو.', NULL, '&nbsp;هغۀ به درې غاښے د پخلى لوښى ته ورننويستلو او چې درې غاښى به څۀ هم راوويستل نو هغه به د اِمام وُو. د هغه ټولو بنى اِسرائيلو سره هم داسې سلوک وشو چې د قربانۍ پېش کولو دپاره سيلا ښار ته راغلى وُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6755, '1 Samuel 2:15', '1 Samuel', 2, 15, '&nbsp;د دې نه علاوه، وازګه به هم لا نۀ وه لرې کړے شوې او نۀ به سوزولے شوې وه چې د اِمام نوکر به راغلو او چې چا به نذرانه پېش کوله نو هغۀ ته به يې وئيل، ”ما له لږه غوښه راکړه چې اِمام له يې وريته کړم، هغه به ستاسو پخه شوې غوښه نۀ قبلوى، صِرف کچه غوښه قبلوى.“', NULL, '&nbsp;د دې نه علاوه، وازګه به هم لا نۀ وه لرې کړے شوې او نۀ به سوزولے شوې وه چې د اِمام نوکر به راغلو او چې چا به نذرانه پېش کوله نو هغۀ ته به يې وئيل، ”ما له لږه غوښه راکړه چې اِمام له يې وريته کړم، هغه به ستاسو پخه شوې غوښه نۀ قبلوى، صِرف کچه غوښه قبلوى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6756, '1 Samuel 2:16', '1 Samuel', 2, 16, '&nbsp;کۀ هغه کس به ورته ووئيل، ”راځئ چې هغه وکړُو چې څۀ صحيح وى او اول وازګه وسوزوو، بيا چې دې څۀ خوښ وى نو هغه واخله.“ خو د اِمام نوکر به ورته ووئيل، ”نه، اوس دا ما له راکړه، کۀ نۀ راکوې، نو زۀ به يې په زور اخلم.“', NULL, '&nbsp;کۀ هغه کس به ورته ووئيل، ”راځئ چې هغه وکړُو چې څۀ صحيح وى او اول وازګه وسوزوو، بيا چې دې څۀ خوښ وى نو هغه واخله.“ خو د اِمام نوکر به ورته ووئيل، ”نه، اوس دا ما له راکړه، کۀ نۀ راکوې، نو زۀ به يې په زور اخلم.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
