(6836, '1 Samuel 6:5', '1 Samuel', 6, 5, '&nbsp;تاسو د دې دانو او مږو نمونې جوړې کړئ چې ستاسو مُلک تباه کوى او تاسو به خامخا د بنى اِسرائيلو د خُدائ پاک درناوے کوئ. کېدے شى چې هغه تاسو له، ستاسو معبودانو او ستاسو مُلک له سزا درکول بند کړى.', NULL, '&nbsp;تاسو د دې دانو او مږو نمونې جوړې کړئ چې ستاسو مُلک تباه کوى او تاسو به خامخا د بنى اِسرائيلو د خُدائ پاک درناوے کوئ. کېدے شى چې هغه تاسو له، ستاسو معبودانو او ستاسو مُلک له سزا درکول بند کړى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
