(6840, '1 Samuel 6:9', '1 Samuel', 6, 9, '&nbsp;چې ګاډۍ روانه وى نو ورته ګورئ، کۀ دا د بيت‌شمس ښار طرف ته لاړه شى، نو د دې مطلب دا دے چې دا د بنى اِسرائيلو خُدائ پاک دے چې هغۀ په مونږ باندې دا سخت افت راوستے دے. خو کۀ داسې نۀ وى، نو بيا به مونږ ته پته ولګى چې هغۀ وبا نۀ وه راوستې، او په خپله داسې وشول.“', NULL, '&nbsp;چې ګاډۍ روانه وى نو ورته ګورئ، کۀ دا د بيت‌شمس ښار طرف ته لاړه شى، نو د دې مطلب دا دے چې دا د بنى اِسرائيلو خُدائ پاک دے چې هغۀ په مونږ باندې دا سخت افت راوستے دے. خو کۀ داسې نۀ وى، نو بيا به مونږ ته پته ولګى چې هغۀ وبا نۀ وه راوستې، او په خپله داسې وشول.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
