(6853, '1 Samuel 7:3', '1 Samuel', 7, 3, '&nbsp;سموئيل بنى اِسرائيلو ته وفرمائيل، ”کۀ تاسو د زړۀ د اخلاصه مالِک خُدائ ته راواوړئ، نو تاسو به خامخا د ټولو پردو معبودانو او عستارات بُتانو نه ځان خلاصوئ. خپل ځانونه مالِک خُدائ ته حواله کړئ او صِرف د هغۀ عبادت کوئ او هغه به تاسو د فلستيانو د زور نه خلاص کړى.“', NULL, '&nbsp;سموئيل بنى اِسرائيلو ته وفرمائيل، ”کۀ تاسو د زړۀ د اخلاصه مالِک خُدائ ته راواوړئ، نو تاسو به خامخا د ټولو پردو معبودانو او عستارات بُتانو نه ځان خلاصوئ. خپل ځانونه مالِک خُدائ ته حواله کړئ او صِرف د هغۀ عبادت کوئ او هغه به تاسو د فلستيانو د زور نه خلاص کړى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6854, '1 Samuel 7:4', '1 Samuel', 7, 4, '&nbsp;نو بنى اِسرائيلو د بعل او عستارات د بُتانو نه خپل ځانونه خلاص کړل او صِرف د مالِک خُدائ عبادت يې کولو.', NULL, '&nbsp;نو بنى اِسرائيلو د بعل او عستارات د بُتانو نه خپل ځانونه خلاص کړل او صِرف د مالِک خُدائ عبادت يې کولو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6855, '1 Samuel 7:5', '1 Samuel', 7, 5, '&nbsp;بيا سموئيل ټول بنى اِسرائيليان راوغوښتل چې په مصفاه کښې راغونډ شى او ورته يې وفرمائيل، ”زۀ به هلته ستاسو دپاره مالِک خُدائ ته سوال وکړم.“', NULL, '&nbsp;بيا سموئيل ټول بنى اِسرائيليان راوغوښتل چې په مصفاه کښې راغونډ شى او ورته يې وفرمائيل، ”زۀ به هلته ستاسو دپاره مالِک خُدائ ته سوال وکړم.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6856, '1 Samuel 7:6', '1 Samuel', 7, 6, '&nbsp;نو هغوئ ټول په مصفاه کښې راغونډ شول. هغوئ څۀ اوبۀ راوويستلې او مالِک خُدائ ته يې د يوې نذرانې په توګه توئ کړې او ټوله ورځ يې روژه ونيوله. هغوئ ووئيل، ”مونږ د مالِک خُدائ خِلاف ګناه کړې ده.“ نو سموئيل په مصفاه کښې د بنى اِسرائيلو مشر جوړ شو.', NULL, '&nbsp;نو هغوئ ټول په مصفاه کښې راغونډ شول. هغوئ څۀ اوبۀ راوويستلې او مالِک خُدائ ته يې د يوې نذرانې په توګه توئ کړې او ټوله ورځ يې روژه ونيوله. هغوئ ووئيل، ”مونږ د مالِک خُدائ خِلاف ګناه کړې ده.“ نو سموئيل په مصفاه کښې د بنى اِسرائيلو مشر جوړ شو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6857, '1 Samuel 7:7', '1 Samuel', 7, 7, '&nbsp;کله چې فلستيان خبر شول چې بنى اِسرائيل په مصفاه کښې راغونډ شوى دى، فلستى بادشاهان د خپلو سړو سره د هغوئ خِلاف جنګ له راووتل. بنى اِسرائيليان د دې نه خبر شول او ويرېدل،', NULL, '&nbsp;کله چې فلستيان خبر شول چې بنى اِسرائيل په مصفاه کښې راغونډ شوى دى، فلستى بادشاهان د خپلو سړو سره د هغوئ خِلاف جنګ له راووتل. بنى اِسرائيليان د دې نه خبر شول او ويرېدل،', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6858, '1 Samuel 7:8', '1 Samuel', 7, 8, '&nbsp;او سموئيل ته يې ووئيل، ”مالِک خُدائ زمونږ خُدائ پاک ته دُعا کول مۀ پرېږده چې مونږ د فلستيانو نه بچ کړى.“', NULL, '&nbsp;او سموئيل ته يې ووئيل، ”مالِک خُدائ زمونږ خُدائ پاک ته دُعا کول مۀ پرېږده چې مونږ د فلستيانو نه بچ کړى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6859, '1 Samuel 7:9', '1 Samuel', 7, 9, '&nbsp;سموئيل يو داسې ګډُورے حلال کړو چې مور يې رودله او د يوې نذرانې په توګه يې ټول مالِک خُدائ ته وسوزولو. بيا يې مالِک خُدائ ته دُعا وکړه چې د بنى اِسرائيلو مدد وکړى او مالِک خُدائ د هغۀ دُعا واورېده.', NULL, '&nbsp;سموئيل يو داسې ګډُورے حلال کړو چې مور يې رودله او د يوې نذرانې په توګه يې ټول مالِک خُدائ ته وسوزولو. بيا يې مالِک خُدائ ته دُعا وکړه چې د بنى اِسرائيلو مدد وکړى او مالِک خُدائ د هغۀ دُعا واورېده.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6860, '1 Samuel 7:10', '1 Samuel', 7, 10, '&nbsp;کله چې سموئيل نذرانه پېش کوله، نو فلستيان د حملې دپاره مخکښې ورغلل، خو بيا هم په هغه وخت مالِک خُدائ د هغوئ خِلاف د يو لوئ تندر په شان آواز وکړو. فلستيان دومره په وارخطايۍ آخته شول چې وتښتېدل.', NULL, '&nbsp;کله چې سموئيل نذرانه پېش کوله، نو فلستيان د حملې دپاره مخکښې ورغلل، خو بيا هم په هغه وخت مالِک خُدائ د هغوئ خِلاف د يو لوئ تندر په شان آواز وکړو. فلستيان دومره په وارخطايۍ آخته شول چې وتښتېدل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6861, '1 Samuel 7:11', '1 Samuel', 7, 11, '&nbsp;بنى اِسرائيليان د مصفاه نه روان شول او تقريباً تر بيت‌کَر پورې په فلستيانو پسې وُو او په لاره باندې يې وژل.', NULL, '&nbsp;بنى اِسرائيليان د مصفاه نه روان شول او تقريباً تر بيت‌کَر پورې په فلستيانو پسې وُو او په لاره باندې يې وژل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
