(6900, '1 Samuel 9:16', '1 Samuel', 9, 16, '&nbsp;”سبا تقريباً په دې وخت به زۀ د بنيامين د قبيلې يو سړے تا له درولېږم، د هغۀ سر په تېلو غوړ کړه چې هغه زما د خلقو بنى اِسرائيلو بادشاه شى. او هغه به هغوئ د فلستيانو نه خلاص کړى. ما د خپلو خلقو تکليف ليدلے دے او د هغوئ فرياد مې اورېدلے دے.“', NULL, '&nbsp;”سبا تقريباً په دې وخت به زۀ د بنيامين د قبيلې يو سړے تا له درولېږم، د هغۀ سر په تېلو غوړ کړه چې هغه زما د خلقو بنى اِسرائيلو بادشاه شى. او هغه به هغوئ د فلستيانو نه خلاص کړى. ما د خپلو خلقو تکليف ليدلے دے او د هغوئ فرياد مې اورېدلے دے.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
