(6904, '1 Samuel 9:20', '1 Samuel', 9, 20, '&nbsp;چې کوم خرونه درې ورځې مخکښې ورک شوى وُو، د هغې فکر مۀ کوئ، هغه پېدا شوى دى. خو دا تۀ او ستا د پلار خاندان دے چې د ټولو بنى اِسرائيلو زړۀ ور پورې تړلے دے.“', NULL, '&nbsp;چې کوم خرونه درې ورځې مخکښې ورک شوى وُو، د هغې فکر مۀ کوئ، هغه پېدا شوى دى. خو دا تۀ او ستا د پلار خاندان دے چې د ټولو بنى اِسرائيلو زړۀ ور پورې تړلے دے.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
