(6908, '1 Samuel 9:24', '1 Samuel', 9, 24, '&nbsp;نو د اخلى پخلى والا د ټولو نه ښۀ غوښه راوړه او د ساؤل په مخکښې يې کېښوده. سموئيل ورته وفرمائيل، ”ګوره، دا هغه ټُکړه ده چې ستا دپاره ساتلے شوې وه. دا وخوره. د دې خلقو د رابللو نه مخکښې دا ما ستا دپاره اېښې وه.“ نو ساؤل په هغه ورځ د سموئيل سره روټۍ وخوړه.', NULL, '&nbsp;نو د اخلى پخلى والا د ټولو نه ښۀ غوښه راوړه او د ساؤل په مخکښې يې کېښوده. سموئيل ورته وفرمائيل، ”ګوره، دا هغه ټُکړه ده چې ستا دپاره ساتلے شوې وه. دا وخوره. د دې خلقو د رابللو نه مخکښې دا ما ستا دپاره اېښې وه.“ نو ساؤل په هغه ورځ د سموئيل سره روټۍ وخوړه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6909, '1 Samuel 9:25', '1 Samuel', 9, 25, '&nbsp;کله چې هغوئ د عبادت ځائ نه ښار ته کوز شول، نو هغوئ په چت باندې د ساؤل دپاره د څملاستو ځائ تيار کړو،', NULL, '&nbsp;کله چې هغوئ د عبادت ځائ نه ښار ته کوز شول، نو هغوئ په چت باندې د ساؤل دپاره د څملاستو ځائ تيار کړو،', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6910, '1 Samuel 9:26', '1 Samuel', 9, 26, '&nbsp;او هغه هلته اودۀ شو. د ساؤل د بادشاه په توګه مقرر کېدل په سحر کښې سموئيل ساؤل ته په چت باندې آواز وکړو، ”پاڅه او زۀ به تا رُخصت کړم.“ ساؤل پاڅېدو او هغه او سموئيل دواړه يو ځائ بهر کوڅې ته لاړل.', NULL, '&nbsp;او هغه هلته اودۀ شو.
</p><h3 class="sectiontitle">د ساؤل د بادشاه په توګه مقرر کېدل</h3>
<p>په سحر کښې سموئيل ساؤل ته په چت باندې آواز وکړو، ”پاڅه او زۀ به تا رُخصت کړم.“ ساؤل پاڅېدو او هغه او سموئيل دواړه يو ځائ بهر کوڅې ته لاړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6911, '1 Samuel 9:27', '1 Samuel', 9, 27, '&nbsp;کله چې هغوئ د ښار سر ته ورسېدل، نو سموئيل ساؤل ته وفرمائيل، ”نوکر ته ووايه چې زمونږ نه مخکښې روان شى.“ نوکر لاړو او سموئيل خپله خبره جارى وساتله، ”لږ وخت دلته ايسار شه، نو زۀ به تا ته د خُدائ پاک د طرف نه يوه خبره وکړم.“', NULL, '&nbsp;کله چې هغوئ د ښار سر ته ورسېدل، نو سموئيل ساؤل ته وفرمائيل، ”نوکر ته ووايه چې زمونږ نه مخکښې روان شى.“ نوکر لاړو او سموئيل خپله خبره جارى وساتله، ”لږ وخت دلته ايسار شه، نو زۀ به تا ته د خُدائ پاک د طرف نه يوه خبره وکړم.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6912, '1 Samuel 10:1', '1 Samuel', 10, 1, '&nbsp;بيا سموئيل د زيتُونو تېلو يو لوښے واخستو او تېل يې د ساؤل په سر واړول، ساؤل يې ښُکل کړو او ورته يې وفرمائيل، ”مالِک خُدائ تا د خپلو خلقو بنى اِسرائيلو دپاره د بادشاه په توګه مقرروى. تۀ به د هغۀ په خلقو بادشاهى کوې او د ټولو دشمنانو نه به يې بچ کوې او دا هغه نښه ده چې تۀ مالِک خُدائ خوښ کړے يې او د هغوئ بادشاه جوړ شوے يې،', NULL, '&nbsp;بيا سموئيل د زيتُونو تېلو يو لوښے واخستو او تېل يې د ساؤل په سر واړول، ساؤل يې ښُکل کړو او ورته يې وفرمائيل، ”مالِک خُدائ تا د خپلو خلقو بنى اِسرائيلو دپاره د بادشاه په توګه مقرروى. تۀ به د هغۀ په خلقو بادشاهى کوې او د ټولو دشمنانو نه به يې بچ کوې او دا هغه نښه ده چې تۀ مالِک خُدائ خوښ کړے يې او د هغوئ بادشاه جوړ شوے يې،', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6913, '1 Samuel 10:2', '1 Samuel', 10, 2, '&nbsp;چې تاسو نن زما نه لاړ شئ، نو د بنيامين په علاقه ضلضع کښې د راحيل د قبر سره نزدې به تاسو د دوو سړو سره مِلاو شئ. هغوئ به تاسو ته ووائى چې تاسو کوم خرونه لټوئ هغه پېدا شوى دى، نو داسې ستاسو پلار به د خرونو په حقله پرېشان نۀ وى خو ستاسو په حقله به پرېشان وى او بيا بيا به تپوسونه کوى چې زما زوئ چرته دے؟', NULL, '&nbsp;چې تاسو نن زما نه لاړ شئ، نو د بنيامين په علاقه ضلضع کښې د راحيل د قبر سره نزدې به تاسو د دوو سړو سره مِلاو شئ. هغوئ به تاسو ته ووائى چې تاسو کوم خرونه لټوئ هغه پېدا شوى دى، نو داسې ستاسو پلار به د خرونو په حقله پرېشان نۀ وى خو ستاسو په حقله به پرېشان وى او بيا بيا به تپوسونه کوى چې زما زوئ چرته دے؟', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6914, '1 Samuel 10:3', '1 Samuel', 10, 3, '&nbsp;کله چې تاسو په تبور کښې پاکې ونې ته ورسېږئ، نو هلته به تاسو د درېو سړو سره مِلاو شئ چې په بيت‌ايل کښې خُدائ پاک ته يوه نذرانه پېش کولو له روان وى. يو به د چېلۍ درې بچى روان کړى وى، بل به درې روټۍ روانې کړې وى او درېم سره به د ميو نه ډکه مشکيزه وى.', NULL, '&nbsp;کله چې تاسو په تبور کښې پاکې ونې ته ورسېږئ، نو هلته به تاسو د درېو سړو سره مِلاو شئ چې په بيت‌ايل کښې خُدائ پاک ته يوه نذرانه پېش کولو له روان وى. يو به د چېلۍ درې بچى روان کړى وى، بل به درې روټۍ روانې کړې وى او درېم سره به د ميو نه ډکه مشکيزه وى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6915, '1 Samuel 10:4', '1 Samuel', 10, 4, '&nbsp;هغوئ به په تاسو سلام واچوى او دوه روټۍ به درته پېش کړى، هغه تاسو قبولې کړئ.', NULL, '&nbsp;هغوئ به په تاسو سلام واچوى او دوه روټۍ به درته پېش کړى، هغه تاسو قبولې کړئ.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6916, '1 Samuel 10:5', '1 Samuel', 10, 5, '&nbsp;بيا به تاسو په جبعه کښې د خُدائ پاک غر ته لاړ شئ، چرته چې د فلستيانو کېمپ دے. ښار ته د ننوتلو په ځائ کښې به تاسو د پېغمبرانو يوې قبيلې سره مِلاو شئ چې په غرۀ باندې د قربان‌ګاه نه راکوزيږى، بينجو، تمبل، شپېلۍ او رباب به غږوى. او هغوئ به په جذبه کښې پېغام ورکوى.', NULL, '&nbsp;بيا به تاسو په جبعه کښې د خُدائ پاک غر ته لاړ شئ، چرته چې د فلستيانو کېمپ دے. ښار ته د ننوتلو په ځائ کښې به تاسو د پېغمبرانو يوې قبيلې سره مِلاو شئ چې په غرۀ باندې د قربان‌ګاه نه راکوزيږى، بينجو، تمبل، شپېلۍ او رباب به غږوى. او هغوئ به په جذبه کښې پېغام ورکوى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
