(6962, '1 Samuel 12:9', '1 Samuel', 12, 9, '&nbsp;خو خلقو مالِک خُدائ خپل خُدائ پاک هېر کړو، نو هغۀ هغوئ سِسيرا ته حواله کړل څوک چې د حصور د ښار د لښکر مشر وو او فلستيانو او د موآب بادشاه ته يې حواله کړل، چې هغوئ ستاسو د پلار نيکۀ خِلاف وجنګيږى او شکست ورکړى.', NULL, '&nbsp;خو خلقو مالِک خُدائ خپل خُدائ پاک هېر کړو، نو هغۀ هغوئ سِسيرا ته حواله کړل څوک چې د حصور د ښار د لښکر مشر وو او فلستيانو او د موآب بادشاه ته يې حواله کړل، چې هغوئ ستاسو د پلار نيکۀ خِلاف وجنګيږى او شکست ورکړى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6963, '1 Samuel 12:10', '1 Samuel', 12, 10, '&nbsp;بيا هغوئ مالِک خُدائ ته وئيل چې، مونږ ګناه کړې ده ځکه مونږ ستا نه واوړېدو او د بعل او عستارات د بُتانو عبادت مو وکړو. مونږ د خپلو دشمنانو نه بچ کړه او مونږ به ستا عبادت کوُو.', NULL, '&nbsp;بيا هغوئ مالِک خُدائ ته وئيل چې، مونږ ګناه کړې ده ځکه مونږ ستا نه واوړېدو او د بعل او عستارات د بُتانو عبادت مو وکړو. مونږ د خپلو دشمنانو نه بچ کړه او مونږ به ستا عبادت کوُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6964, '1 Samuel 12:11', '1 Samuel', 12, 11, '&nbsp;مالِک خُدائ جدعون، برق او اِفتاح راولېږل او په آخر کښې يې زۀ راولېږلم. مونږ هر يو تاسو د ګېرچاپېره دشمنانو نه بچ کړئ او تاسو په خېر سره ژوند تېرولو.', NULL, '&nbsp;مالِک خُدائ جدعون، برق او اِفتاح راولېږل او په آخر کښې يې زۀ راولېږلم. مونږ هر يو تاسو د ګېرچاپېره دشمنانو نه بچ کړئ او تاسو په خېر سره ژوند تېرولو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6965, '1 Samuel 12:12', '1 Samuel', 12, 12, '&nbsp;خو کله چې تاسو وليدل چې د عمون بادشاه ناحس په تاسو حمله کوى، نو تاسو مالِک خُدائ رد کړو اګر چې مالِک خُدائ ستاسو خُدائ پاک ستاسو بادشاه وو خو تاسو بيا هم ما ته ووئيل چې مونږ يو بادشاه غواړُو چې په مونږ بادشاهى کوى.', NULL, '&nbsp;خو کله چې تاسو وليدل چې د عمون بادشاه ناحس په تاسو حمله کوى، نو تاسو مالِک خُدائ رد کړو اګر چې مالِک خُدائ ستاسو خُدائ پاک ستاسو بادشاه وو خو تاسو بيا هم ما ته ووئيل چې مونږ يو بادشاه غواړُو چې په مونږ بادشاهى کوى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6966, '1 Samuel 12:13', '1 Samuel', 12, 13, '&nbsp;نو اوس هغه بادشاه دا دے چې تاسو خوښ کړے دے، تاسو هغه غوښتے وو او مالِک خُدائ تاسو له درکړو.', NULL, '&nbsp;نو اوس هغه بادشاه دا دے چې تاسو خوښ کړے دے، تاسو هغه غوښتے وو او مالِک خُدائ تاسو له درکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6967, '1 Samuel 12:14', '1 Samuel', 12, 14, '&nbsp;کۀ تاسو د مالِک خُدائ نه يرېږئ، د هغۀ خِدمت او تابعدارى کوئ او د هغۀ د حُکم نه سرکشى مۀ کوئ او کۀ تاسو او هغه بادشاه چې په تاسو بادشاهى کوى د مالِک خُدائ د خپل خُدائ پاک تابعدارى کوئ نو ستاسو هر کار به سم وى.', NULL, '&nbsp;کۀ تاسو د مالِک خُدائ نه يرېږئ، د هغۀ خِدمت او تابعدارى کوئ او د هغۀ د حُکم نه سرکشى مۀ کوئ او کۀ تاسو او هغه بادشاه چې په تاسو بادشاهى کوى د مالِک خُدائ د خپل خُدائ پاک تابعدارى کوئ نو ستاسو هر کار به سم وى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6968, '1 Samuel 12:15', '1 Samuel', 12, 15, '&nbsp;خو کۀ تاسو مالِک خُدائ ته غوږ نۀ نيسئ او د هغۀ د حُکمونو نافرمانى کوئ، نو هغه به ستاسو او ستاسو د بادشاه خِلاف شى.', NULL, '&nbsp;خو کۀ تاسو مالِک خُدائ ته غوږ نۀ نيسئ او د هغۀ د حُکمونو نافرمانى کوئ، نو هغه به ستاسو او ستاسو د بادشاه خِلاف شى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6969, '1 Samuel 12:16', '1 Samuel', 12, 16, '&nbsp;نو بيا دلته ودرېږئ او تاسو به په خپلو سترګو هغه لوئ لوئ کارونه ووينئ چې مالِک خُدائ يې کوى.', NULL, '&nbsp;نو بيا دلته ودرېږئ او تاسو به په خپلو سترګو هغه لوئ لوئ کارونه ووينئ چې مالِک خُدائ يې کوى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6970, '1 Samuel 12:17', '1 Samuel', 12, 17, '&nbsp;تاسو ته پته ده چې دا د غنمو د لَو وخت دے چې دا د باران موسم نۀ وى خو زۀ به مالِک خُدائ ته سوال وکړم او هغه به تندر او باران راولېږى. کله چې داسې وشى نو تاسو ته به پته ولګى چې تاسو د مالِک خُدائ خِلاف يوه لويه ګناه کړې ده کله چې تاسو د هغۀ نه يو بادشاه وغوښتو.“', NULL, '&nbsp;تاسو ته پته ده چې دا د غنمو د لَو وخت دے چې دا د باران موسم نۀ وى خو زۀ به مالِک خُدائ ته سوال وکړم او هغه به تندر او باران راولېږى. کله چې داسې وشى نو تاسو ته به پته ولګى چې تاسو د مالِک خُدائ خِلاف يوه لويه ګناه کړې ده کله چې تاسو د هغۀ نه يو بادشاه وغوښتو.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6971, '1 Samuel 12:18', '1 Samuel', 12, 18, '&nbsp;نو سموئيل سوال وکړو او هم په هغه ورځ مالِک خُدائ تندر او باران راولېږلو. نو ټول خلق د مالِک خُدائ او سموئيل نه ويرېدل،', NULL, '&nbsp;نو سموئيل سوال وکړو او هم په هغه ورځ مالِک خُدائ تندر او باران راولېږلو. نو ټول خلق د مالِک خُدائ او سموئيل نه ويرېدل،', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6972, '1 Samuel 12:19', '1 Samuel', 12, 19, '&nbsp;او هغوئ سموئيل ته ووئيل، ”مالِک خُدائ خپل خُدائ پاک ته زمونږ دپاره سوال وکړه، نو داسې به مونږ نۀ مړۀ کيږُو. اوس مونږ ته دا پته لګېدلې ده چې د نورو ټولو ګناهونو نه علاوه مونږ دا ګناه هم کړې ده چې يو بادشاه مو غوښتے دے.“', NULL, '&nbsp;او هغوئ سموئيل ته ووئيل، ”مالِک خُدائ خپل خُدائ پاک ته زمونږ دپاره سوال وکړه، نو داسې به مونږ نۀ مړۀ کيږُو. اوس مونږ ته دا پته لګېدلې ده چې د نورو ټولو ګناهونو نه علاوه مونږ دا ګناه هم کړې ده چې يو بادشاه مو غوښتے دے.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6973, '1 Samuel 12:20', '1 Samuel', 12, 20, '&nbsp;سموئيل ورته وفرمائيل، ”مۀ يرېږئ، اګر چې تاسو داسې بد عمل کړے هم دے خو د مالِک خُدائ نه مۀ اوړئ او د خپل ټول زړۀ سره د هغۀ خِدمت کوئ.', NULL, '&nbsp;سموئيل ورته وفرمائيل، ”مۀ يرېږئ، اګر چې تاسو داسې بد عمل کړے هم دے خو د مالِک خُدائ نه مۀ اوړئ او د خپل ټول زړۀ سره د هغۀ خِدمت کوئ.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
