(6983, '1 Samuel 13:5', '1 Samuel', 13, 5, '&nbsp;فلستيان د بنى اِسرائيلو خِلاف د جنګ دپاره راغونډ شول، د هغوئ سره دېرش زره جنګى ګاډۍ وې، شپږ زره په آسونو سوارۀ کسان او دومره ډېر فوجيان ورسره وُو لکه چې په سمندر کښې څومره شګې دى. هغوئ د بيت‌آون نمرخاتۀ طرف ته مِکماس ته لاړل او هلته يې خېمې ولګولې.', NULL, '&nbsp;فلستيان د بنى اِسرائيلو خِلاف د جنګ دپاره راغونډ شول، د هغوئ سره دېرش زره جنګى ګاډۍ وې، شپږ زره په آسونو سوارۀ کسان او دومره ډېر فوجيان ورسره وُو لکه چې په سمندر کښې څومره شګې دى. هغوئ د بيت‌آون نمرخاتۀ طرف ته مِکماس ته لاړل او هلته يې خېمې ولګولې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
