(6989, '1 Samuel 13:11', '1 Samuel', 13, 11, '&nbsp;خو سموئيل وفرمائيل، ”تا څۀ کړى دى؟“ ساؤل جواب ورکړو، ”خلق زما نه تلل، خو چې تا څنګه فرمائيلى وُو نو تۀ په مقرر وخت رانۀ غلې، د دې نه علاوه، فلستيان په مِکماس کښې د جنګ دپاره راغونډيږى.', NULL, '&nbsp;خو سموئيل وفرمائيل، ”تا څۀ کړى دى؟“ ساؤل جواب ورکړو، ”خلق زما نه تلل، خو چې تا څنګه فرمائيلى وُو نو تۀ په مقرر وخت رانۀ غلې، د دې نه علاوه، فلستيان په مِکماس کښې د جنګ دپاره راغونډيږى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6990, '1 Samuel 13:12', '1 Samuel', 13, 12, '&nbsp;نو زما خيال دا وو چې فلستيان دلته په ما باندې په جِلجال کښې حمله کوى، خو ما مالِک خُدائ ته سوال نۀ وو کړے او زۀ مجبور وم چې نذرانه پېش کړم.“', NULL, '&nbsp;نو زما خيال دا وو چې فلستيان دلته په ما باندې په جِلجال کښې حمله کوى، خو ما مالِک خُدائ ته سوال نۀ وو کړے او زۀ مجبور وم چې نذرانه پېش کړم.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
(6991, '1 Samuel 13:13', '1 Samuel', 13, 13, '&nbsp;سموئيل ورته په جواب کښې وفرمائيل، ”داسې کول بې‌وقوفى وه. تا د مالِک خُدائ خپل خُدائ پاک حُکم نۀ دے منلے. کۀ تا منلے وے نو هغۀ به تۀ او ستا اولاد بادشاهان جوړ کړى وئ چې همېشه دپاره په بنى اِسرائيلو حکومت وکړئ.', NULL, '&nbsp;سموئيل ورته په جواب کښې وفرمائيل، ”داسې کول بې‌وقوفى وه. تا د مالِک خُدائ خپل خُدائ پاک حُکم نۀ دے منلے. کۀ تا منلے وے نو هغۀ به تۀ او ستا اولاد بادشاهان جوړ کړى وئ چې همېشه دپاره په بنى اِسرائيلو حکومت وکړئ.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757184, 1761757184),
